
export interface Gua64 { number: number; name: string; nameEn: string; upper: string; lower: string; symbol: string; element: string; judgment: string; judgmentEn: string; image: string; imageEn: string; meaning: string; meaningEn: string; keywords: string[]; keywordsEn: string[]; yaoTexts: string[]; yaoTextsEn: string[]; advice: string; adviceEn: string; fortune: '大吉' | '吉' | '中吉' | '中平' | '小凶' | '凶' | '大凶'; fortuneEn: 'Great Fortune' | 'Fortune' | 'Moderate Fortune' | 'Neutral' | 'Minor Misfortune' | 'Misfortune' | 'Great Misfortune'; }

export const GUA64_LIST: Gua64[] = [
  { number: 1, name: '乾为天', nameEn: 'The Creative', upper: '乾', lower: '乾', symbol: '䷀', element: '金', judgment: '元亨利贞。', judgmentEn: 'The Creative works sublime success, furthering through perseverance.', image: '天行健，君子以自强不息。', imageEn: 'Heaven moves vigorously; the superior man strengthens himself ceaselessly.', meaning: '乾卦象征天，代表刚健、创造、进取。此卦大吉，表示事业顺利，前途光明。', meaningEn: 'Qian symbolizes Heaven, representing vigor, creativity, and progress. Great fortune.', keywords: ['创造','进取','刚健','领导','成功'], keywordsEn: ['Creation','Progress','Vigor','Leadership','Success'], yaoTexts: ['潜龙勿用。','见龙在田，利见大人。','君子终日乾乾，夕惕若厉，无咎。','或跃在渊，无咎。','飞龙在天，利见大人。','亢龙有悔。'], yaoTextsEn: ['Hidden dragon, do not act.','Dragon appearing in the field, it furthers one to see the great man.','All day long the superior man is creatively active. At nightfall his mind is still beset with cares. Danger. No blame.','Wavering flight over the depths. No blame.','Flying dragon in the heavens. It furthers one to see the great man.','Arrogant dragon will have cause to repent.'], advice: '把握时机，积极进取，但不可骄傲自满。', adviceEn: 'Seize the opportunity and progress actively, but avoid arrogance.', fortune: '大吉', fortuneEn: 'Great Fortune' },
  { number: 2, name: '坤为地', nameEn: 'The Receptive', upper: '坤', lower: '坤', symbol: '䷁', element: '土', judgment: '元亨，利牝马之贞。', judgmentEn: 'The Receptive brings about sublime success, furthering through the perseverance of a mare.', image: '地势坤，君子以厚德载物。', imageEn: 'Earth is receptive; the superior man carries virtue with a generous nature.', meaning: '坤卦象征地，代表柔顺、包容、承载。此卦大吉，表示厚德载物，事业稳固。', meaningEn: 'Kun symbolizes Earth, representing gentleness, inclusiveness, and bearing. Great fortune.', keywords: ['柔顺','包容','承载','稳重','厚德'], keywordsEn: ['Gentleness','Inclusiveness','Bearing','Steadiness','Virtue'], yaoTexts: ['履霜，坚冰至。','直方大，不习无不利。','含章可贞。或从王事，无成有终。','括囊，无咎无誉。','黄裳，元吉。','龙战于野，其血玄黄。'], yaoTextsEn: ['When there is hoarfrost underfoot, solid ice is not far off.','Straight, square, great. Without purpose, yet nothing remains unfurthered.','Hidden lines. One is able to remain persevering. If by chance you are in the service of a king, seek not works, but bring to completion.','A tied-up sack. No blame, no praise.','Yellow lower garment. Supreme good fortune.','Dragons fight in the meadow. Their blood is black and yellow.'], advice: '以柔克刚，包容万物，厚德载物。', adviceEn: 'Overcome hardness with softness, embrace all things with virtue.', fortune: '大吉', fortuneEn: 'Great Fortune' },
  { number: 3, name: '水雷屯', nameEn: 'Difficulty at the Beginning', upper: '坎', lower: '震', symbol: '䷂', element: '水', judgment: '元亨利贞，勿用有攸往，利建侯。', judgmentEn: 'Difficulty at the Beginning works supreme success, furthering through perseverance. Nothing should be undertaken. It furthers one to appoint helpers.', image: '云雷屯，君子以经纶。', imageEn: 'Clouds and thunder: the image of Difficulty at the Beginning. The superior man brings order out of confusion.', meaning: '屯卦象征万物始生之难。虽有困难，但坚持下去终能成功。', meaningEn: 'Zhun symbolizes the difficulty of beginning. Persevere and success will come.', keywords: ['困难','开始','创业','坚持','新生'], keywordsEn: ['Difficulty','Beginning','Entrepreneurship','Perseverance','New birth'], yaoTexts: ['磐桓；利居贞，利建侯。','屯如邅如，乘马班如。匪寇婚媾，女子贞不字，十年乃字。','即鹿无虞，惟入于林中。君子几不如舍，往吝。','乘马班如，求婚媾，往吉，无不利。','屯其膏，小贞吉，大贞凶。','乘马班如，泣血涟如。'], yaoTextsEn: ['Hesitation and hindrance. It furthers one to remain persevering. It furthers one to appoint helpers.','Difficulties pile up. Horse and wagon part. He is not a robber; he wants to woo when the time comes. The maiden is chaste, she does not pledge herself. Ten years, then she pledges herself.','Whoever hunts deer without the forester only loses his way in the forest. The superior man understands the signs of the time and prefers to desist. To go on brings humiliation.','Horse and wagon part. Strive for union. To go brings good fortune. Everything acts to further.','If you are sincere and loyally attached, you are rich in your neighbor.','Horse and wagon part. Bloody tears flow.'], advice: '创业之初困难重重，需耐心积累，不可冒进。', adviceEn: 'The beginning is difficult; accumulate patiently and avoid rashness.', fortune: '中吉', fortuneEn: 'Moderate Fortune' },
  { number: 4, name: '山水蒙', nameEn: 'Youthful Folly', upper: '艮', lower: '坎', symbol: '䷃', element: '土', judgment: '亨。匪我求童蒙，童蒙求我。', judgmentEn: 'Youthful Folly has success. It is not I who seek the young fool; the young fool seeks me.', image: '山下出泉，蒙；君子以果行育德。', imageEn: 'A spring on the mountain: the image of Youthful Folly. The superior man fosters his character by thoroughness in all that he does.', meaning: '蒙卦象征蒙昧，需要启蒙教育。虚心求教，方能进步。', meaningEn: 'Meng symbolizes ignorance and the need for education. Seek knowledge humbly.', keywords: ['启蒙','教育','学习','虚心','成长'], keywordsEn: ['Enlightenment','Education','Learning','Humility','Growth'], yaoTexts: ['发蒙，利用刑人，用说桎梏，以往吝。','包蒙吉；纳妇吉；子克家。','勿用取女；见金夫，不有躬，无攸利。','困蒙，吝。','童蒙，吉。','击蒙；不利为寇，利御寇。'], yaoTextsEn: ['To make a fool develop it furthers one to apply discipline. The fetters should be removed. To go on in this way brings humiliation.','To bear with fools in kindliness brings good fortune. To know how to take women brings good fortune. The son is capable of taking charge of the household.','Take not a maiden who, when she sees a man of bronze, loses possession of herself. Nothing furthers.','Entangled folly brings humiliation.','Childlike folly brings good fortune.','In punishing folly it does not further one to commit transgressions. The only thing that furthers is to prevent transgressions.'], advice: '虚心学习，接受启蒙，不可自以为是。', adviceEn: 'Learn humbly, accept guidance, avoid self-conceit.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 5, name: '水天需', nameEn: 'Waiting', upper: '坎', lower: '乾', symbol: '䷄', element: '水', judgment: '有孚，光亨，贞吉。利涉大川。', judgmentEn: 'Waiting. If you are sincere, you have light and success. Perseverance brings good fortune. It furthers one to cross the great water.', image: '云上于天，需；君子以饮食宴乐。', imageEn: 'Clouds rise up to heaven: the image of Waiting. The superior man eats and drinks, is joyous and of good cheer.', meaning: '需卦象征等待。时机未到，宜静候佳音，养精蓄锐。', meaningEn: 'Xu symbolizes waiting. Wait for the right time and conserve energy.', keywords: ['等待','耐心','时机','准备','信任'], keywordsEn: ['Waiting','Patience','Timing','Preparation','Trust'], yaoTexts: ['需于郊，利用恒，无咎。','需于沙，小有言，终吉。','需于泥，致寇至。','需于血，出自穴。','需于酒食，贞吉。','入于穴，有不速之客三人来，敬之终吉。'], yaoTextsEn: ['Waiting in the meadow. It furthers one to abide in what endures. No blame.','Waiting on the sand. There is some gossip. The end brings good fortune.','Waiting in the mud brings about enemies.','Waiting in blood. One gets out of the pit.','Waiting at meat and drink. Perseverance brings good fortune.','One falls into the pit. Three uninvited guests arrive. Honor them, and in the end there will be good fortune.'], advice: '耐心等待，养精蓄锐，时机成熟自然成功。', adviceEn: 'Wait patiently, conserve energy, success comes when the time is right.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 6, name: '天水讼', nameEn: 'Conflict', upper: '乾', lower: '坎', symbol: '䷅', element: '金', judgment: '有孚，窒惕，中吉，终凶。', judgmentEn: 'Conflict. You are sincere and are being obstructed. A cautious halt halfway brings good fortune. Going through to the end brings misfortune.', image: '天与水违行，讼；君子以作事谋始。', imageEn: 'Heaven and water go their opposite ways: the image of Conflict. The superior man, in commencing his undertakings, takes the difficulty into account.', meaning: '讼卦象征争讼。宜和解，不宜争讼到底。', meaningEn: 'Song symbolizes conflict. Seek reconciliation rather than prolonged dispute.', keywords: ['争讼','冲突','和解','谨慎','退让'], keywordsEn: ['Conflict','Dispute','Reconciliation','Caution','Compromise'], yaoTexts: ['不永所事，小有言，终吉。','不克讼，归而逋，其邑人三百户，无眚。','食旧德，贞厉，终吉。或从王事，无成。','不克讼，复即命，渝安贞，吉。','讼元吉。','或锡之鞶带，终朝三褫之。'], yaoTextsEn: ['If one does not perpetuate the affair, there is a little gossip. In the end, good fortune comes.','One cannot engage in conflict; one returns home, gives way. The people of his town, three hundred households, remain free of guilt.','To nourish oneself on ancient virtue induces perseverance. Danger. In the end, good fortune comes. If by chance you are in the service of a king, seek not works.','One cannot engage in conflict. One turns back and submits to fate, changes one\'s attitude, and finds peace in perseverance. Good fortune.','To contend before him brings supreme good fortune.','Even if by chance a leather belt is bestowed on one, by the end of the morning it will have been snatched away three times.'], advice: '避免争讼，以和为贵，退一步海阔天空。', adviceEn: 'Avoid conflict, value harmony, a step back brings vastness.', fortune: '小凶', fortuneEn: 'Minor Misfortune' },
  { number: 7, name: '地水师', nameEn: 'The Army', upper: '坤', lower: '坎', symbol: '䷆', element: '土', judgment: '贞，丈人吉，无咎。', judgmentEn: 'The Army. The army needs perseverance and a strong man. Good fortune without blame.', image: '地中有水，师；君子以容民畜众。', imageEn: 'In the middle of the earth is water: the image of the Army. The superior man increases his masses by generosity toward the people.', meaning: '师卦象征军队。需要纪律严明，统帅有方。', meaningEn: 'Shi symbolizes the army. Requires discipline and capable leadership.', keywords: ['军队','纪律','领导','团结','战争'], keywordsEn: ['Army','Discipline','Leadership','Unity','War'], yaoTexts: ['师出以律，否臧凶。','在师中，吉，无咎，王三锡命。','师或舆尸，凶。','师左次，无咎。','田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶。','大君有命，开国承家，小人勿用。'], yaoTextsEn: ['An army must set forth in proper order. If the order is not good, misfortune threatens.','In the midst of the army. Good fortune. No blame. The king bestows a triple decoration.','Perchance the army carries corpses in the wagon. Misfortune.','The army retreats. No blame.','There is game in the field. It furthers one to catch it. Without blame. Let the eldest lead the army. The younger transports corpses. Then perseverance brings misfortune.','The great prince issues commands, founds states, vests families with fiefs. Inferior people should not be employed.'], advice: '纪律严明，团结一致，但不可滥用武力。', adviceEn: 'Maintain discipline and unity, but do not abuse force.', fortune: '中平', fortuneEn: 'Neutral' },
  { number: 8, name: '水地比', nameEn: 'Holding Together', upper: '坎', lower: '坤', symbol: '䷇', element: '水', judgment: '吉。原筮元永贞，无咎。不宁方来，后夫凶。', judgmentEn: 'Holding Together brings good fortune. Inquire of the oracle once again whether you possess sublimity, constancy, and perseverance; then there is no blame.', image: '地上有水，比；先王以建万国，亲诸侯。', imageEn: 'On the earth is water: the image of Holding Together. The kings of antiquity thereby established the various states and had friendly relations with the feudal lords.', meaning: '比卦象征亲近、团结。团结他人，共同发展。', meaningEn: 'Bi symbolizes closeness and unity. Unite with others for mutual growth.', keywords: ['团结','亲近','合作','依附','和谐'], keywordsEn: ['Unity','Closeness','Cooperation','Attachment','Harmony'], yaoTexts: ['有孚比之，无咎。有孚盈缶，终来有它，吉。','比之自内，贞吉。','比之匪人。','外比之，贞吉。','显比，王用三驱，失前禽。邑人不诫，吉。','比之无首，凶。'], yaoTextsEn: ['Hold to him in truth and loyalty; this is without blame. Truth, like a full earthen bowl. By the end, coming from elsewhere, good fortune.','Hold to him inwardly. Perseverance brings good fortune.','You hold together with the wrong people.','You hold together outwardly also. Perseverance brings good fortune.','Manifestation of holding together. In the hunt the king uses beaters on three sides only and foregoes game that runs off in front. The citizens need no warning. Good fortune.','He finds no head for holding together. Misfortune.'], advice: '团结志同道合之人，远离小人。', adviceEn: 'Unite with like-minded people, stay away from petty people.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 9, name: '风天小畜', nameEn: 'The Taming Power of the Small', upper: '巽', lower: '乾', symbol: '䷈', element: '木', judgment: '亨。密云不雨，自我西郊。', judgmentEn: 'The Taming Power of the Small has success. Dense clouds, no rain from our western region.', image: '风行天上，小畜；君子以懿文德。', imageEn: 'The wind drives across heaven: the image of the Taming Power of the Small. The superior man refines the outward aspect of his nature.', meaning: '小畜卦象征小有蓄积。力量尚弱，宜蓄积待发。', meaningEn: 'Xiao Chu symbolizes small accumulation. Strength is still weak; accumulate and wait.', keywords: ['蓄积','等待','小有成就','准备','节制'], keywordsEn: ['Accumulation','Waiting','Small success','Preparation','Temperance'], yaoTexts: ['复自道，何其咎，吉。','牵复，吉。','舆说辐，夫妻反目。','有孚，血去惕出，无咎。','有孚挛如，富以其邻。','既雨既处，尚德载，妇贞厉。月几望，君子征凶。'], yaoTextsEn: ['Return from the way. How could there be blame in this? Good fortune.','He allows himself to be drawn into returning. Good fortune.','The spokes burst out of the wagon wheels. Man and wife roll their eyes.','If you are sincere, blood vanishes and fear gives way. No blame.','If you are sincere and loyally attached, you are rich in your neighbor.','The rain comes, there is rest. This is due to the lasting effect of character. Perseverance of the woman brings danger. The moon is nearly full. If the superior man persists, misfortune comes.'], advice: '小有蓄积，不可急于求成，宜静待时机。', adviceEn: 'Small accumulation; do not rush, wait for the right time.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 10, name: '天泽履', nameEn: 'Treading', upper: '乾', lower: '兑', symbol: '䷉', element: '金', judgment: '履虎尾，不咥人，亨。', judgmentEn: 'Treading. Treading upon the tail of the tiger. It does not bite the man. Success.', image: '上天下泽，履；君子以辨上下，定民志。', imageEn: 'Heaven above, the lake below: the image of Treading. The superior man discriminates between high and low, and strengthens the people\'s mind.', meaning: '履卦象征谨慎行事。如履薄冰，谨慎则吉。', meaningEn: 'Lu symbolizes cautious conduct. Walk on thin ice carefully for good fortune.', keywords: ['谨慎','行事','礼仪','规矩','小心'], keywordsEn: ['Caution','Conduct','Etiquette','Rules','Care'], yaoTexts: ['素履，往无咎。','履道坦坦，幽人贞吉。','眇能视，跛能履，履虎尾，咥人，凶。武人为于大君。','履虎尾，愬愬终吉。','夬履，贞厉。','视履考祥，其旋元吉。'], yaoTextsEn: ['Simple conduct. Progress without blame.','Treading a smooth, level course. The perseverance of a dark man brings good fortune.','A one-eyed man is able to see, a lame man is able to tread. He treads on the tail of the tiger. The tiger bites the man. Misfortune.','He treads on the tail of the tiger. Caution and circumspection lead ultimately to good fortune.','Resolute conduct. Perseverance with awareness of danger.','Look to your conduct and weigh the favorable signs. When everything is fulfilled, supreme good fortune comes.'], advice: '行事谨慎，遵守礼仪，不可冒失。', adviceEn: 'Act cautiously, observe etiquette, avoid recklessness.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 11, name: '地天泰', nameEn: 'Peace', upper: '坤', lower: '乾', symbol: '䷊', element: '土', judgment: '小往大来，吉亨。', judgmentEn: 'Peace. The small departs, the great approaches. Good fortune. Success.', image: '天地交，泰；后以财成天地之道，辅相天地之宜，以左右民。', imageEn: 'Heaven and earth unite: the image of Peace. The ruler divides and completes the course of heaven and earth; he furthers and regulates the gifts of heaven and earth, and so aids the people.', meaning: '泰卦象征通泰。天地交泰，万物亨通。', meaningEn: 'Tai symbolizes peace and prosperity. Heaven and earth unite, all things flourish.', keywords: ['通泰','和谐','繁荣','交流','顺利'], keywordsEn: ['Peace','Harmony','Prosperity','Exchange','Smooth'], yaoTexts: ['拔茅茹，以其汇，征吉。','包荒，用冯河，不遐遗，朋亡，得尚于中行。','无平不陂，无往不复，艰贞无咎。勿恤其孚，于食有福。','翩翩不富，以其邻，不戒以孚。','帝乙归妹，以祉元吉。','城复于隍，勿用师。自邑告命，贞吝。'], yaoTextsEn: ['When ribbon grass is pulled up, the sod comes with it. Each according to his kind. Undertakings bring good fortune.','Bearing with the uncultured in gentleness, fording the river with resolution, not neglecting what is distant, not regarding one\'s companions: thus one may manage to walk in the middle.','No plain not followed by a slope. No going not followed by a return. He who remains persevering in danger is without blame. Do not complain about this truth; enjoy the fortune and rest.','He flutters down, not boasting of his wealth, together with his neighbor, guileless and sincere.','The sovereign I gave his daughter in marriage. This brings blessing and supreme good fortune.','The wall falls back into the moat. Use no army now. Make your commands known within your own town. Perseverance brings humiliation.'], advice: '天地交泰，把握时机，广结善缘。', adviceEn: 'Heaven and earth unite; seize the opportunity and build good relationships.', fortune: '大吉', fortuneEn: 'Great Fortune' },
  { number: 12, name: '天地否', nameEn: 'Standstill', upper: '乾', lower: '坤', symbol: '䷋', element: '金', judgment: '否之匪人，不利君子贞，大往小来。', judgmentEn: 'Standstill. Evil people do not further the perseverance of the superior man. The great departs; the small approaches.', image: '天地不交，否；君子以俭德辟难，不可荣以禄。', imageEn: 'Heaven and earth do not unite: the image of Standstill. The superior man falls back upon his inner worth in order to escape the difficulties. He does not permit himself to be honored with revenue.', meaning: '否卦象征闭塞。天地不交，万物不通。', meaningEn: 'Pi symbolizes stagnation. Heaven and earth do not unite, all things are blocked.', keywords: ['闭塞','困难','停滞','保守','等待'], keywordsEn: ['Stagnation','Difficulty','Standstill','Conservatism','Waiting'], yaoTexts: ['拔茅茹，以其汇，贞吉亨。','包承。小人吉，大人否，亨。','包羞。','有命无咎，畴离祉。','休否，大人吉。其亡其亡，系于苞桑。','倾否，先否后喜。'], yaoTextsEn: ['When ribbon grass is pulled up, the sod comes with it. Each according to his kind. Perseverance brings good fortune and success.','They bear and endure. This means good fortune for inferior people. The standstill serves to help the great man to attain success.','They bear shame.','He who acts at the command of the highest remains without blame. Those of like mind partake of the blessing.','Standstill is giving way. Good fortune for the great man. "What if it should fail, what if it should fail?" In this way he ties it to a cluster of mulberry shoots.','The standstill comes to an end. First standstill, then good fortune.'], advice: '闭塞之时宜退守，等待时机转变。', adviceEn: 'In times of stagnation, retreat and wait for change.', fortune: '凶', fortuneEn: 'Misfortune' },
  { number: 13, name: '天火同人', nameEn: 'Fellowship with Men', upper: '乾', lower: '离', symbol: '䷌', element: '金', judgment: '同人于野，亨。利涉大川，利君子贞。', judgmentEn: 'Fellowship with Men in the open. Success. It furthers one to cross the great water. The perseverance of the superior man furthers.', image: '天与火，同人；君子以类族辨物。', imageEn: 'Heaven together with fire: the image of Fellowship with Men. The superior man organizes the clans and makes distinctions between things.', meaning: '同人卦象征志同道合。与人和同，事业可成。', meaningEn: 'Tong Ren symbolizes like-minded fellowship. Unity with others brings success.', keywords: ['团结','合作','志同道合','交流','和谐'], keywordsEn: ['Unity','Cooperation','Like-minded','Exchange','Harmony'], yaoTexts: ['同人于门，无咎。','同人于宗，吝。','伏戎于莽，升其高陵，三岁不兴。','乘其墉，弗克攻，吉。','同人，先号咷而后笑。大师克相遇。','同人于郊，无悔。'], yaoTextsEn: ['Fellowship with men at the gate. No blame.','Fellowship with men in the clan. Humiliation.','He hides weapons in the thicket; he climbs the high hill in front of it. For three years he does not rise up.','He climbs up on his wall; he cannot attack. Good fortune.','Men bound in fellowship first weep and lament, but afterward they laugh. After great struggles they succeed in meeting.','Fellowship with men in the meadow. No remorse.'], advice: '与志同道合者合作，但需明辨是非。', adviceEn: 'Cooperate with like-minded people, but distinguish right from wrong.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 14, name: '火天大有', nameEn: 'Possession in Great Measure', upper: '离', lower: '乾', symbol: '䷍', element: '火', judgment: '元亨。', judgmentEn: 'Possession in Great Measure. Supreme success.', image: '火在天上，大有；君子以遏恶扬善，顺天休命。', imageEn: 'Fire in heaven above: the image of Possession in Great Measure. The superior man curbs evil and furthers good, and thereby obeys the benevolent will of heaven.', meaning: '大有卦象征大丰收。光明普照，万物丰盛。', meaningEn: 'Da You symbolizes great abundance. Light shines everywhere, all things flourish.', keywords: ['丰收','富有','光明','成功','丰盛'], keywordsEn: ['Abundance','Wealth','Light','Success','Plenty'], yaoTexts: ['无交害，匪咎，艰则无咎。','大车以载，有攸往，无咎。','公用亨于天子，小人弗克。','匪其彭，无咎。','厥孚交如，威如，吉。','自天佑之，吉无不利。'], yaoTextsEn: ['No relationship with what is harmful; there is no blame in this. If one remains conscious of the difficulty, there is no blame.','A big wagon for loading. One may undertake something. No blame.','A prince offers it to the Son of Heaven. A petty man cannot do this.','He makes a difference between himself and his neighbor. No blame.','He whose truth is accessible, yet dignified, has good fortune.','He is blessed by heaven. Good fortune. Nothing that does not further.'], advice: '大丰收之时，宜行善积德，与人为善。', adviceEn: 'In times of abundance, practice virtue and kindness.', fortune: '大吉', fortuneEn: 'Great Fortune' },
  { number: 15, name: '地山谦', nameEn: 'Modesty', upper: '坤', lower: '艮', symbol: '䷎', element: '土', judgment: '亨，君子有终。', judgmentEn: 'Modesty creates success. The superior man carries things through.', image: '地中有山，谦；君子以裒多益寡，称物平施。', imageEn: 'Within the earth, a mountain: the image of Modesty. The superior man reduces that which is too much, and augments that which is too little. He weighs things and makes them equal.', meaning: '谦卦象征谦虚。谦虚使人进步，骄傲使人落后。', meaningEn: 'Qian symbolizes modesty. Modesty leads to progress; arrogance leads to decline.', keywords: ['谦虚','低调','礼让','修养','内敛'], keywordsEn: ['Modesty','Humility','Courtesy','Cultivation','Restraint'], yaoTexts: ['谦谦君子，用涉大川，吉。','鸣谦，贞吉。','劳谦君子，有终吉。','无不利，撝谦。','不富，以其邻，利用侵伐，无不利。','鸣谦，利用行师，征邑国。'], yaoTextsEn: ['A superior man modest about his modesty may cross the great water. Good fortune.','Modesty that comes to expression. Perseverance brings good fortune.','A superior man of modesty and merit carries things to conclusion. Good fortune.','Nothing that would not further modesty.','No boasting of wealth before one\'s neighbor. It is favorable to attack with force. Nothing that would not further.','In modesty, expression. It furthers one to set armies marching to chastise one\'s own city and one\'s country.'], advice: '谦虚待人，低调行事，终有大成。', adviceEn: 'Be modest and low-key in conduct, and great success will come.', fortune: '大吉', fortuneEn: 'Great Fortune' },
  { number: 16, name: '雷地豫', nameEn: 'Enthusiasm', upper: '震', lower: '坤', symbol: '䷏', element: '木', judgment: '利建侯行师。', judgmentEn: 'Enthusiasm. It furthers one to install helpers and to set armies marching.', image: '雷出地奋，豫；先王以作乐崇德，殷荐之上帝，以配祖考。', imageEn: 'Thunder comes resounding out of the earth: the image of Enthusiasm. The kings of antiquity made music in order to honor merit, and offered it with splendor to the Supreme Deity, inviting their ancestors to be present.', meaning: '豫卦象征喜悦和乐。但不可沉溺享乐，宜有所节制。', meaningEn: 'Yu symbolizes joy and enthusiasm. But do not indulge; practice moderation.', keywords: ['喜悦','和乐','准备','享乐','节制'], keywordsEn: ['Joy','Enthusiasm','Preparation','Pleasure','Moderation'], yaoTexts: ['鸣豫，凶。','介于石，不终日，贞吉。','盱豫，悔。迟有悔。','由豫，大有得。勿疑。朋盍簪。','贞疾，恒不死。','冥豫，成有渝，无咎。'], yaoTextsEn: ['Enthusiasm that expresses itself brings misfortune.','Firm as a rock. Not a whole day. Perseverance brings good fortune.','Enthusiasm that looks upward creates remorse. Hesitation brings remorse.','The source of enthusiasm. He achieves great things. Doubt not. You gather friends around you as a hair clasp gathers the hair.','Persistently ill, and still does not die.','The tingling of enthusiasm. But if after completion one changes, there is no blame.'], advice: '和乐之时不忘准备，享乐之中保持节制。', adviceEn: 'In joy, do not forget preparation; in pleasure, maintain moderation.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 17, name: '泽雷随', nameEn: 'Following', upper: '兑', lower: '震', symbol: '䷐', element: '金', judgment: '元亨利贞，无咎。', judgmentEn: 'Following has supreme success. Perseverance furthers. No blame.', image: '泽中有雷，随；君子以向晦入宴息。', imageEn: 'Thunder in the middle of the lake: the image of Following. The superior man at evening goes indoors for rest and recuperation.', meaning: '随卦象征随从。顺势而为，随机应变。', meaningEn: 'Sui symbolizes following. Go with the flow and adapt to circumstances.', keywords: ['随从','顺应','灵活','变通','适应'], keywordsEn: ['Following','Adaptation','Flexibility','Adjustment','Accommodation'], yaoTexts: ['官有渝，贞吉。出门交有功。','系小子，失丈夫。','系丈夫，失小子。随有求得，利居贞。','随有获，贞凶。有孚在道，以明，何咎。','孚于嘉，吉。','拘系之，乃从维之。王用亨于西山。'], yaoTextsEn: ['The standard is changing. Perseverance brings good fortune. To go out of the door in company produces deeds.','If one clings to the little boy, one loses the strong man.','If one clings to the strong man, one loses the little boy. Through following one finds what one seeks. It furthers one to remain persevering.','Following creates possession. Perseverance brings misfortune. To put one\'s trust in the way of the superior man brings good fortune.','Truth in the center. Radiant, it is the king\'s property.','In the face of the enticement to return to the way, the heart of the superior man turns away. The king sacrifices on the Western Mountain.'], advice: '顺势而为，随机应变，但不可盲从。', adviceEn: 'Follow the trend and adapt, but do not follow blindly.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 18, name: '山风蛊', nameEn: 'Work on What Has Been Spoiled', upper: '艮', lower: '巽', symbol: '䷑', element: '土', judgment: '元亨，利涉大川。先甲三日，后甲三日。', judgmentEn: 'Work on What Has Been Spoiled has supreme success. It furthers one to cross the great water. Before the starting point, three days. After the starting point, three days.', image: '山下有风，蛊；君子以振民育德。', imageEn: 'The wind blows low on the mountain: the image of Decay. The superior man stirs up the people and strengthens their spirit.', meaning: '蛊卦象征腐败。需要革新除弊，振衰起敝。', meaningEn: 'Gu symbolizes decay. Reform and remove corruption to revitalize.', keywords: ['腐败','革新','整顿','改革','除弊'], keywordsEn: ['Decay','Reform','Rectification','Reorganization','Removal'], yaoTexts: ['干父之蛊，有子，考无咎，厉终吉。','干母之蛊，不可贞。','干父之蛊，小有悔，无大咎。','裕父之蛊，往见吝。','干父之蛊，用誉。','不事王侯，高尚其事。'], yaoTextsEn: ['Setting right what has been spoiled by the father. If there is a son, no blame rests upon the departed father. Danger. In the end good fortune.','Setting right what has been spoiled by the mother. One must not be too persevering.','Setting right what has been spoiled by the father. There will be a little remorse. No great blame.','Tolerating what has been spoiled by the father. In continuing one sees humiliation.','Setting right what has been spoiled by the father. One meets with praise.','He does not serve kings and princes, sets himself higher goals.'], advice: '发现问题及时整顿，革新除弊方能新生。', adviceEn: 'Address problems promptly; reform brings renewal.', fortune: '中吉', fortuneEn: 'Moderate Fortune' },
  { number: 19, name: '地泽临', nameEn: 'Approach', upper: '坤', lower: '兑', symbol: '䷒', element: '土', judgment: '元，亨，利，贞。至于八月有凶。', judgmentEn: 'Approach has supreme success. Perseverance furthers. When the eighth month comes, there will be misfortune.', image: '泽上有地，临；君子以教思无穷，容保民无疆。', imageEn: 'The earth above the lake: the image of Approach. The superior man, in accordance with this, educates people, and in his thoughts does not limit himself.', meaning: '临卦象征临近。居高临下，宜施教化。', meaningEn: 'Lin symbolizes approach. From a high position, educate and guide.', keywords: ['临近','监督','教化','领导','管理'], keywordsEn: ['Approach','Supervision','Education','Leadership','Management'], yaoTexts: ['咸临，贞吉。','咸临，吉无不利。','甘临，无攸利。既忧之，无咎。','至临，无咎。','知临，大君之宜，吉。','敦临，吉无不利。'], yaoTextsEn: ['Joint approach. Perseverance brings good fortune.','Joint approach. Good fortune. Everything furthers.','Comfortable approach. Nothing that would further. If one is induced to grieve over it, one becomes free of blame.','Complete approach. No blame.','Wise approach. This is right for a great prince. Good fortune.','Greathearted approach. Good fortune. No blame.'], advice: '居高临下之时，宜以教化为主，不可压迫。', adviceEn: 'From a high position, focus on education, not oppression.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 20, name: '风地观', nameEn: 'Contemplation', upper: '巽', lower: '坤', symbol: '䷓', element: '木', judgment: '盥而不荐，有孚颙若。', judgmentEn: 'Contemplation. The ablution has been made, but not yet the offering. Full of trust they look up to him.', image: '风行地上，观；先王以省方，观民设教。', imageEn: 'The wind blows over the earth: the image of Contemplation. The kings of antiquity visited the regions of the world, contemplated the people, and gave them instruction.', meaning: '观卦象征观察。登高望远，洞察事物本质。', meaningEn: 'Guan symbolizes observation. Look from a high place to see the essence of things.', keywords: ['观察','洞察','审视','学习','远见'], keywordsEn: ['Observation','Insight','Examination','Learning','Foresight'], yaoTexts: ['童观，小人无咎，君子吝。','窥观，利女贞。','观我生，进退。','观国之光，利用宾于王。','观我生，君子无咎。','观其生，君子无咎。'], yaoTextsEn: ['Boylike contemplation. For an inferior man, no blame. For a superior man, humiliation.','Contemplation through the crack of the door. Furthering for the perseverance of a woman.','Contemplation of my life decides the choice between advance and retreat.','Contemplation of the light of the kingdom. It furthers one to exert influence as the guest of a king.','Contemplation of my life. The superior man is without blame.','Contemplation of his life. The superior man is without blame.'], advice: '登高望远，洞察本质，以明智决策。', adviceEn: 'Look from a high place, see the essence, and make wise decisions.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 21, name: '火雷噬嗑', nameEn: 'Biting Through', upper: '离', lower: '震', symbol: '䷔', element: '火', judgment: '亨。利用狱。', judgmentEn: 'Biting Through has success. It is favorable to let justice be administered.', image: '雷电噬嗑；先王以明罚勅法。', imageEn: 'Thunder and lightning: the image of Biting Through. The kings of antiquity made firm the laws through clearly defined penalties.', meaning: '噬嗑卦象征咬合。明罚勅法，以正纲纪。', meaningEn: 'Shi He symbolizes biting through. Enforce laws and penalties to maintain order.', keywords: ['刑罚','法律','正义','咬合','整顿'], keywordsEn: ['Penalty','Law','Justice','Biting','Rectification'], yaoTexts: ['屦校灭趾，无咎。','噬肤灭鼻，无咎。','噬腊肉，遇毒；小吝，无咎。','噬干胏，得金矢，利艰贞，吉。','噬干肉，得黄金，贞厉，无咎。','何校灭耳，凶。'], yaoTextsEn: ['His feet are fastened in the stocks, so that his toes disappear. No blame.','Bites through tender meat, so that his nose disappears. No blame.','Bites on old dried meat and strikes on something poisonous. Slight humiliation. No blame.','Bites on dried gristly meat. Receives metal arrows. It furthers one to be mindful of difficulties and to be persevering. Good fortune.','Bites on dried lean meat. Receives yellow gold. Perseveringly aware of danger. No blame.','His neck is fastened in the wooden cangue, so that his ears disappear. Misfortune.'], advice: '明罚勅法，公正执法，但不可过度。', adviceEn: 'Enforce laws justly, but do not overdo it.', fortune: '中平', fortuneEn: 'Neutral' },
  { number: 22, name: '山火贲', nameEn: 'Grace', upper: '艮', lower: '离', symbol: '䷕', element: '土', judgment: '亨。小利有攸往。', judgmentEn: 'Grace has success. In small matters it is favorable to undertake something.', image: '山下有火，贲；君子以明庶政，无敢折狱。', imageEn: 'Fire at the foot of the mountain: the image of Grace. The superior man causes his commands to be known and does not allow himself to be misled in lawsuits.', meaning: '贲卦象征文饰。文质彬彬，然后君子。', meaningEn: 'Bi symbolizes grace and ornamentation. Cultivate both substance and form.', keywords: ['文饰','美丽','礼仪','修养','外表'], keywordsEn: ['Ornamentation','Beauty','Etiquette','Cultivation','Appearance'], yaoTexts: ['贲其趾，舍车而徒。','贲其须。','贲如濡如，永贞吉。','贲如皤如，白马翰如，匪寇婚媾。','贲于丘园，束帛戋戋，吝，终吉。','白贲，无咎。'], yaoTextsEn: ['He lends grace to his toes, leaves the carriage, and walks.','Lends grace to the beard on his chin.','Graceful and moist. Constant perseverance brings good fortune.','Gracefully adorned, the white horse. He is not a robber, he will woo at the right time.','Grace in hills and gardens. The roll of silk is meager and small. Humiliation, but in the end good fortune.','Simple grace. No blame.'], advice: '文质兼备，注重内在修养，不可徒有其表。', adviceEn: 'Combine substance with form; focus on inner cultivation, not just appearance.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 23, name: '山地剥', nameEn: 'Splitting Apart', upper: '艮', lower: '坤', symbol: '䷖', element: '土', judgment: '不利有攸往。', judgmentEn: 'Splitting Apart. It does not further one to go anywhere.', image: '山附于地，剥；上以厚下安宅。', imageEn: 'The mountain rests on the earth: the image of Splitting Apart. Those above secure their position by giving generously to those below.', meaning: '剥卦象征剥落。事物衰败，宜退守自保。', meaningEn: 'Bo symbolizes decay. Things decline; retreat and protect yourself.', keywords: ['剥落','衰败','退守','保守','等待'], keywordsEn: ['Decay','Decline','Retreat','Conservatism','Waiting'], yaoTexts: ['剥床以足，蔑贞凶。','剥床以辨，蔑贞凶。','剥之，无咎。','剥床以肤，凶。','贯鱼，以宫人宠，无不利。','硕果不食，君子得舆，小人剥庐。'], yaoTextsEn: ['The leg of the bed is split. Those who persevere are destroyed. Misfortune.','The bed is split at the edge. Those who persevere are destroyed. Misfortune.','He splits with them. No blame.','The bed is split up to the skin. Misfortune.','A shoal of fishes. Favor comes through the court ladies. Everything acts to further.','There is a large fruit still uneaten. The superior man receives a carriage. The house of the inferior man is split apart.'], advice: '事物衰败之时，宜退守自保，等待时机。', adviceEn: 'In decline, retreat and protect yourself, waiting for better times.', fortune: '凶', fortuneEn: 'Misfortune' },
  { number: 24, name: '地雷复', nameEn: 'Return', upper: '坤', lower: '震', symbol: '䷗', element: '土', judgment: '亨。出入无疾，朋来无咎。反复其道，七日来复，利有攸往。', judgmentEn: 'Return. Success. Going out and coming in without harm. Friends come without blame. To and fro goes the way. On the seventh day comes return. It furthers one to have somewhere to go.', image: '雷在地中，复；先王以至日闭关，商旅不行，后不省方。', imageEn: 'Thunder within the earth: the image of the Turning Point. The kings of antiquity closed the passes at the time of solstice. Merchants and strangers did not go about, and the ruler did not travel through the provinces.', meaning: '复卦象征回复。一阳来复，万物更生。', meaningEn: 'Fu symbolizes return. One yang returns, all things are renewed.', keywords: ['回复','新生','循环','开始','希望'], keywordsEn: ['Return','Renewal','Cycle','Beginning','Hope'], yaoTexts: ['不远复，无祗悔，元吉。','休复，吉。','频复，厉无咎。','中行独复。','敦复，无悔。','迷复，凶，有灾眚。用行师，终有大败，以其国君，凶；至于十年，不克征。'], yaoTextsEn: ['Return from a short distance. No need for remorse. Great good fortune.','Quiet return. Good fortune.','Repeated return. Danger. No blame.','Walking in the midst of others, one returns alone.','Noblehearted return. No remorse.','Missing the return. Misfortune. Misfortune from within and without. If armies are set marching in this way, one will in the end suffer a great defeat, disastrous for the ruler of the state. For ten years it will not be possible to attack again.'], advice: '一阳来复，把握时机，重新开始。', adviceEn: 'One yang returns; seize the opportunity and start anew.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 25, name: '天雷无妄', nameEn: 'Innocence', upper: '乾', lower: '震', symbol: '䷘', element: '金', judgment: '元亨利贞。其匪正有眚，不利有攸往。', judgmentEn: 'Innocence. Supreme success. Perseverance furthers. If someone is not as he should be, he has misfortune, and it does not further him to undertake anything.', image: '天下雷行，物与无妄；先王以茂对时，育万物。', imageEn: 'Under heaven thunder rolls: All things attain the natural state of innocence. The kings of antiquity, in accordance with this, made their regulations in harmony with the seasons, thereby fostering all that is growing.', meaning: '无妄卦象征无妄。真实无妄，顺其自然。', meaningEn: 'Wu Wang symbolizes innocence. Be genuine and follow nature.', keywords: ['无妄','真实','自然','正直','诚信'], keywordsEn: ['Innocence','Truth','Nature','Integrity','Honesty'], yaoTexts: ['无妄，往吉。','不耕获，不菑畬，则利有攸往。','无妄之灾，或系之牛，行人之得，邑人之灾。','可贞，无咎。','无妄之疾，勿药有喜。','无妄，行有眚，无攸利。'], yaoTextsEn: ['Innocent behavior brings good fortune.','If one does not count on the harvest while plowing, nor on the use of the ground while clearing it, it furthers one to undertake something.','Undeserved misfortune. The cow that was tethered by someone is the wanderer\'s gain, the citizen\'s loss.','He who can be persevering remains without blame.','Useless innocence. The first line of the hexagram is changed. One does not move the cow. The wanderer\'s gain, the citizen\'s loss.','Innocent action brings misfortune. Nothing furthers.'], advice: '真实无妄，顺其自然，不可强求。', adviceEn: 'Be genuine, follow nature, do not force things.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 26, name: '山天大畜', nameEn: 'The Taming Power of the Great', upper: '艮', lower: '乾', symbol: '䷙', element: '土', judgment: '利贞，不家食吉，利涉大川。', judgmentEn: 'The Taming Power of the Great. Perseverance furthers. Not eating at home brings good fortune. It furthers one to cross the great water.', image: '天在山中，大畜；君子以多识前言往行，以畜其德。', imageEn: 'Heaven within the mountain: the image of the Taming Power of the Great. The superior man acquaints himself with many sayings of antiquity and many deeds of the past, in order to strengthen his character thereby.', meaning: '大畜卦象征大蓄积。蓄积德行，以待时机。', meaningEn: 'Da Chu symbolizes great accumulation. Accumulate virtue and wait for the right time.', keywords: ['蓄积','德行','等待','准备','修养'], keywordsEn: ['Accumulation','Virtue','Waiting','Preparation','Cultivation'], yaoTexts: ['有厉利已。','舆说輹。','良马逐，利艰贞。曰闲舆卫，利有攸往。','童牛之牿，元吉。','豶豕之牙，吉。','何天之衢，亨。'], yaoTextsEn: ['Danger is at hand. It furthers one to desist.','The axletrees are taken from the wagon.','A good horse that follows others. Awareness of danger, with perseverance, furthers. Practice chariot driving and armed defense daily. It furthers one to have somewhere to go.','The headboard of a young bull. Great good fortune.','The tusk of a gelded boar. Good fortune.','In command of the sign of heaven. Supreme good fortune.'], advice: '大蓄积之时，修养德行，等待时机成熟。', adviceEn: 'In times of great accumulation, cultivate virtue and wait.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 27, name: '山雷颐', nameEn: 'The Corners of the Mouth', upper: '艮', lower: '震', symbol: '䷚', element: '土', judgment: '贞吉。观颐，自求口实。', judgmentEn: 'The Corners of the Mouth. Perseverance brings good fortune. Pay heed to the providing of nourishment and to what a man seeks to fill his own mouth with.', image: '山下有雷，颐；君子以慎言语，节饮食。', imageEn: 'At the foot of the mountain, thunder: the image of Providing Nourishment. The superior man is careful of his words and temperate in eating and drinking.', meaning: '颐卦象征颐养。慎言语，节饮食，修身养性。', meaningEn: 'Yi symbolizes nourishment. Be careful with words, moderate in diet, cultivate oneself.', keywords: ['颐养','饮食','言语','修养','节制'], keywordsEn: ['Nourishment','Diet','Speech','Cultivation','Moderation'], yaoTexts: ['舍尔灵龟，观我朵颐，凶。','六二：颠颐，拂经，于丘颐，征凶。','拂颐，贞凶，十年勿用，无攸利。','颠颐吉，虎视眈眈，其欲逐逐，无咎。','拂经，居贞吉，不可涉大川。','由颐，厉吉，利涉大川。'], yaoTextsEn: ['You let your magic tortoise go, and look at me with the corners of your mouth drooping. Misfortune.','Turning to the summit for nourishment, deviating from the path to seek nourishment from the hill. Continuing to do this brings misfortune.','Turning away from nourishment. Perseverance brings misfortune. Do not act thus for ten years. Nothing serves to further.','Turning to the summit for nourishment. Good fortune. Gazing steadily, with a tiger\'s desire. No blame.','Turning away from the path. To remain persevering brings good fortune. One should not cross the great water.','The source of nourishment. Awareness of danger brings good fortune. It furthers one to cross the great water.'], advice: '慎言语，节饮食，修身养性，颐养天年。', adviceEn: 'Be careful with words, moderate in diet, cultivate yourself for a long life.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 28, name: '泽风大过', nameEn: 'Preponderance of the Great', upper: '兑', lower: '巽', symbol: '䷛', element: '金', judgment: '栋桡，利有攸往，亨。', judgmentEn: 'Preponderance of the Great. The ridgepole sags to the breaking point. It furthers one to have somewhere to go. Success.', image: '泽灭木，大过；君子以独立不惧，遁世无闷。', imageEn: 'The lake rises above the trees: the image of Preponderance of the Great. The superior man, when he stands alone, is unconcerned, and if he has to renounce the world, he is undaunted.', meaning: '大过卦象征大过。非常之时，需非常之举。', meaningEn: 'Da Guo symbolizes great excess. Extraordinary times require extraordinary measures.', keywords: ['大过','非常','超越','危机','独立'], keywordsEn: ['Excess','Extraordinary','Transcendence','Crisis','Independence'], yaoTexts: ['藉用白茅，无咎。','枯杨生稊，老夫得其女妻，无不利。','栋桡，凶。','栋隆，吉；有它吝。','枯杨生华，老妇得士夫，无咎无誉。','过涉灭顶，凶，无咎。'], yaoTextsEn: ['To spread white rushes underneath. No blame.','A dry poplar sprouts at the root. An older man takes a young wife. Everything furthers.','The ridgepole sags to the breaking point. Misfortune.','The ridgepole is braced. Good fortune. If there are ulterior motives, it is humiliating.','A withered poplar puts forth flowers. An older woman takes a husband. No blame. No praise.','One must go through the water. It goes over one\'s head. Misfortune. No blame.'], advice: '非常之时，需独立不惧，但不可冒进。', adviceEn: 'In extraordinary times, be fearless but not reckless.', fortune: '中平', fortuneEn: 'Neutral' },
  { number: 29, name: '坎为水', nameEn: 'The Abysmal', upper: '坎', lower: '坎', symbol: '䷜', element: '水', judgment: '习坎，有孚，维心亨，行有尚。', judgmentEn: 'The Abysmal repeated. If you are sincere, you have success in your heart, and whatever you do succeeds.', image: '水洊至，习坎；君子以常德行，习教事。', imageEn: 'Water flows on uninterruptedly and reaches its goal: the image of the Abysmal repeated. The superior man practices the virtue of his heart and carries on the business of teaching.', meaning: '坎卦象征险陷。身处险境，需保持诚信。', meaningEn: 'Kan symbolizes danger. In peril, maintain sincerity and trust.', keywords: ['险陷','困难','诚信','坚持','智慧'], keywordsEn: ['Danger','Difficulty','Sincerity','Perseverance','Wisdom'], yaoTexts: ['习坎，入于坎窞，凶。','坎有险，求小得。','来之坎坎，险且枕，入于坎窞，勿用。','樽酒簋贰，用缶，纳约自牖，终无咎。','坎不盈，只既平，无咎。','系用徽纆，寘于丛棘，三岁不得，凶。'], yaoTextsEn: ['In the abyss one falls into a pit. Misfortune.','The abyss is dangerous. One should strive for small things only.','Forward and backward, abyss on abyss. In danger like this, pause at first and wait. Otherwise you will fall into a pit in the abyss. Do not act.','A jug of wine, a bowl of rice with it; earthen vessels simply handed in through the window. There is certainly no blame in this.','The abyss is not filled to overflowing, it is filled only to the rim. No blame.','Bound with cords and ropes, shut in between thorn-hedged prison walls. For three years one does not find the way. Misfortune.'], advice: '身处险境，保持诚信，谨慎行事。', adviceEn: 'In danger, maintain sincerity and act cautiously.', fortune: '小凶', fortuneEn: 'Minor Misfortune' },
  { number: 30, name: '离为火', nameEn: 'The Clinging', upper: '离', lower: '离', symbol: '䷝', element: '火', judgment: '利贞，亨。畜牝牛，吉。', judgmentEn: 'The Clinging. Perseverance furthers. It brings success. Care of the cow brings good fortune.', image: '明两作，离；大人以继明照于四方。', imageEn: 'That which is bright rises twice: the image of Fire. The great man, in accordance with this, cultivates his brightness and illumines the four regions of the world.', meaning: '离卦象征光明。光明普照，文明昌盛。', meaningEn: 'Li symbolizes brightness and clarity. Light shines everywhere, civilization flourishes.', keywords: ['光明','文明','依附','美丽','智慧'], keywordsEn: ['Brightness','Civilization','Attachment','Beauty','Wisdom'], yaoTexts: ['履错然，敬之，无咎。','黄离，元吉。','日昃之离，不鼓缶而歌，则大耋之嗟，凶。','突如其来如，焚如，死如，弃如。','出涕沱若，戚嗟若，吉。','王用出征，有嘉折首，获匪其丑，无咎。'], yaoTextsEn: ['The footprints run crisscross. If one is seriously intent, no blame.','Yellow light. Supreme good fortune.','In the light of the setting sun, men either beat the pot and sing or loudly bewail the approach of old age. Misfortune.','Its coming is sudden; it flames up, dies down, is thrown away.','Tears in floods, sighing and lamenting. Good fortune.','The king uses him to march forth and chastise. Then it is best to kill the leaders and take captive the followers. No blame.'], advice: '光明之时，宜文明以止，不可过度。', adviceEn: 'In times of light, be civilized and temperate, not excessive.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 31, name: '泽山咸', nameEn: 'Influence', upper: '兑', lower: '艮', symbol: '䷞', element: '金', judgment: '亨，利贞，取女吉。', judgmentEn: 'Influence. Success. Perseverance furthers. To take a maiden to wife brings good fortune.', image: '山上有泽，咸；君子以虚受人。', imageEn: 'A lake on the mountain: the image of Influence. The superior man encourages people to approach him by his readiness to receive them.', meaning: '咸卦象征感应。以虚受人，感应天地。', meaningEn: 'Xian symbolizes influence. Receive others with openness and sincerity.', keywords: ['感应','感情','交流','虚心','吸引'], keywordsEn: ['Influence','Feeling','Exchange','Openness','Attraction'], yaoTexts: ['咸其拇。','咸其腓，凶，居吉。','咸其股，执其随，往吝。','贞吉悔亡，憧憧往来，朋从尔思。','咸其脢，无悔。','咸其辅颊舌。'], yaoTextsEn: ['The influence shows itself in the big toe.','The influence shows itself in the calves of the legs. Misfortune. Tarrying brings good fortune.','The influence shows itself in the thighs. Holds to that which follows it. To continue is humiliating.','Perseverance brings good fortune. Remorse disappears. If a man is agitated in mind, and his thoughts go hither and thither, only those friends on whom he fixes his conscious thoughts will follow.','The influence shows itself in the back of the neck. No remorse.','The influence shows itself in the jaws, cheeks, and tongue.'], advice: '以虚受人，真诚感应，感情自然流露。', adviceEn: 'Receive with openness, be sincere, and feelings will flow naturally.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 32, name: '雷风恒', nameEn: 'Duration', upper: '震', lower: '巽', symbol: '䷟', element: '木', judgment: '亨，无咎，利贞，利有攸往。', judgmentEn: 'Duration. Success. No blame. Perseverance furthers. It furthers one to have somewhere to go.', image: '雷风，恒；君子以立不易方。', imageEn: 'Thunder and wind: the image of Duration. The superior man stands firm and does not change his direction.', meaning: '恒卦象征恒久。持之以恒，方能成功。', meaningEn: 'Heng symbolizes duration. Persevere consistently to achieve success.', keywords: ['恒久','坚持','稳定','持久','不变'], keywordsEn: ['Duration','Perseverance','Stability','Persistence','Constancy'], yaoTexts: ['浚恒，贞凶，无攸利。','悔亡。','不恒其德，或承之羞，贞吝。','田无禽。','恒其德，贞，妇人吉，夫子凶。','振恒，凶。'], yaoTextsEn: ['Seeking duration too hastily brings misfortune persistently. Nothing that would further.','Remorse disappears.','He who does not give duration to his character meets with humiliation. Persistent humiliation.','No game in the field.','Giving duration to one\'s character through perseverance. This is good fortune for a woman, misfortune for a man.','Restlessness as an enduring state brings misfortune.'], advice: '持之以恒，坚守正道，但不可固执不变。', adviceEn: 'Persevere in the right way, but do not be stubbornly unchanging.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 33, name: '天山遁', nameEn: 'Retreat', upper: '乾', lower: '艮', symbol: '䷠', element: '金', judgment: '亨，小利贞。', judgmentEn: 'Retreat. Success. In what is small, perseverance furthers.', image: '天下有山，遁；君子以远小人，不恶而严。', imageEn: 'Mountain under heaven: the image of Retreat. The superior man keeps the inferior man at a distance, not angrily but with reserve.', meaning: '遁卦象征退避。远小人，不恶而严。', meaningEn: 'Dun symbolizes retreat. Keep petty people at a distance, not with anger but with dignity.', keywords: ['退避','隐退','远离','自保','等待'], keywordsEn: ['Retreat','Withdrawal','Distance','Self-protection','Waiting'], yaoTexts: ['遁尾，厉，勿用有攸往。','执之用黄牛之革，莫之胜说。','系遁，有疾厉，畜臣妾吉。','好遁君子吉，小人否。','嘉遁，贞吉。','肥遁，无不利。'], yaoTextsEn: ['At the tail in retreat. This is dangerous. One must not wish to undertake anything.','He holds him fast with yellow oxhide. No one can tear him loose.','A halted retreat is nerve-wracking and dangerous. To retain people as men- and maidservants brings good fortune.','Voluntary retreat brings good fortune to the superior man and downfall to the inferior man.','Friendly retreat. Perseverance brings good fortune.','Cheerful retreat. Everything serves to further.'], advice: '适时退避，远小人，保全自身。', adviceEn: 'Retreat at the right time, keep distance from petty people, protect yourself.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 34, name: '雷天大壮', nameEn: 'The Power of the Great', upper: '震', lower: '乾', symbol: '䷡', element: '木', judgment: '利贞。', judgmentEn: 'The Power of the Great. Perseverance furthers.', image: '雷在天上，大壮；君子以非礼弗履。', imageEn: 'Thunder in heaven above: the image of the Power of the Great. The superior man does not tread upon paths that do not accord with established order.', meaning: '大壮卦象征大壮。壮盛之时，宜守正道。', meaningEn: 'Da Zhuang symbolizes great power. In times of strength, uphold the right way.', keywords: ['大壮','强盛','力量','正直','守礼'], keywordsEn: ['Great Power','Strength','Force','Integrity','Propriety'], yaoTexts: ['壮于趾，征凶，有孚。','贞吉。','小人用壮，君子用罔，贞厉。羝羊触藩，羸其角。','贞吉悔亡，藩决不羸，壮于大舆之輹。','丧羊于易，无悔。','羝羊触藩，不能退，不能遂，无攸利，艰则吉。'], yaoTextsEn: ['Power in the toes. Continuing brings misfortune. This is certainly true.','Perseverance brings good fortune.','The inferior man relies on power. The superior man relies on the way. Perseverance brings danger. The goat butts against the hedge and gets its horns entangled.','Perseverance brings good fortune. Remorse disappears. The hedge opens; there is no entanglement. Power depends upon the axle of a big wagon.','The goat loses himself in the field. No remorse.','The goat butts against the hedge. He cannot go backward, he cannot go forward. Nothing serves to further. If one notes the difficulty, this brings good fortune.'], advice: '壮盛之时，守正道，不可恃强凌弱。', adviceEn: 'In times of strength, uphold the right way; do not bully the weak.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 35, name: '火地晋', nameEn: 'Progress', upper: '离', lower: '坤', symbol: '䷢', element: '火', judgment: '康侯用锡马蕃庶，昼日三接。', judgmentEn: 'Progress. The powerful prince is honored with horses in large numbers. In a single day he is granted audience three times.', image: '明出地上，晋；君子以自昭明德。', imageEn: 'The sun rises over the earth: the image of Progress. The superior man makes himself bright and clear.', meaning: '晋卦象征晋升。光明上升，事业进步。', meaningEn: 'Jin symbolizes progress. Light rises, career advances.', keywords: ['晋升','进步','光明','上升','发展'], keywordsEn: ['Progress','Advancement','Light','Rise','Development'], yaoTexts: ['晋如，摧如，贞吉。罔孚，裕无咎。','晋如，愁如，贞吉。受兹介福，于其王母。','众允，悔亡。','晋如鼫鼠，贞厉。','悔亡，失得勿恤，往吉无不利。','晋其角，维用伐邑，厉吉无咎，贞吝。'], yaoTextsEn: ['Progressing, but turned back. Perseverance brings good fortune. If one meets with no confidence, one should remain calm. No mistake.','Progressing, but in sorrow. Perseverance brings good fortune. Then one obtains great happiness from one\'s ancestress.','All are in accord. Remorse disappears.','Progress like a hamster. Perseverance brings danger.','Remorse disappears. Take not gain and loss to heart. Undertakings bring good fortune. Everything serves to further.','Progressing with the horns. It furthers one to punish one\'s own city. To be persevering brings danger. No blame. To be continously aware of danger brings good fortune.'], advice: '晋升之时，宜光明正大，自昭明德。', adviceEn: 'In times of advancement, be upright and make your virtue shine.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 36, name: '地火明夷', nameEn: 'Darkening of the Light', upper: '坤', lower: '离', symbol: '䷣', element: '土', judgment: '利艰贞。', judgmentEn: 'Darkening of the Light. In adversity it furthers one to be persevering.', image: '明入地中，明夷；君子以莅众，用晦而明。', imageEn: 'The light has sunk into the earth: the image of Darkening of the Light. The superior man, in managing his men, uses obscurity but is himself bright.', meaning: '明夷卦象征光明受损。身处逆境，宜韬光养晦。', meaningEn: 'Ming Yi symbolizes darkening of light. In adversity, hide your light and bide your time.', keywords: ['光明受损','逆境','韬光养晦','隐藏','等待'], keywordsEn: ['Darkened Light','Adversity','Concealment','Hiding','Waiting'], yaoTexts: ['明夷于飞，垂其翼。君子于行，三日不食，有攸往，主人有言。','明夷，夷于左股，用拯马壮，吉。','明夷于南狩，得其大首，不可疾贞。','入于左腹，获明夷之心，出于门庭。','箕子之明夷，利贞。','不明晦，初登于天，后入于地。'], yaoTextsEn: ['Darkening of the light during flight. He drops his wings. The superior man, while eating, does not rejoice. While traveling, he does not stop. The host has words.','Darkening of the light injures him in the left thigh. He gives aid with the strength of a horse. Good fortune.','Darkening of the light during the hunt in the south. Their great leader is captured. One must not expect perseverance too soon.','He penetrates the left side of the belly. One gets at the very heart of the darkening of the light, and leaves gate and courtyard.','Darkening of the light as with Prince Chi. Perseverance furthers.','Not light but darkness. First he climbed up to heaven, then he plunged into the depths of the earth.'], advice: '光明受损之时，宜韬光养晦，等待时机。', adviceEn: 'When light is dimmed, conceal your abilities and wait for better times.', fortune: '凶', fortuneEn: 'Misfortune' },
  { number: 37, name: '风火家人', nameEn: 'The Family', upper: '巽', lower: '离', symbol: '䷤', element: '木', judgment: '利女贞。', judgmentEn: 'The Family. The perseverance of the woman furthers.', image: '风自火出，家人；君子以言有物，而行有恒。', imageEn: 'The wind comes forth from fire: the image of the Family. The superior man has substance in his words and duration in his way of life.', meaning: '家人卦象征家庭。女主内，男主外，家庭和睦。', meaningEn: 'Jia Ren symbolizes the family. Inner and outer harmony brings family prosperity.', keywords: ['家庭','和睦','责任','教养','秩序'], keywordsEn: ['Family','Harmony','Responsibility','Education','Order'], yaoTexts: ['闲有家，悔亡。','无攸遂，在中馈。','家人嗃嗃，悔厉吉；妇子嘻嘻，终吝。','富家，大吉。','王假有家，勿恤吉。','有孚威如，终吉。'], yaoTextsEn: ['He establishes order in the family. Remorse disappears.','She does not follow whims. She takes care of the food.','When tempers flare up in the family, too great severity brings remorse. Good fortune. When woman and child dally and laugh, it leads in the end to humiliation.','She is the treasure of the house. Great good fortune.','As a king he approaches his family. Fear not. Good fortune.','His work commands respect. In the end good fortune comes.'], advice: '家庭和睦，各司其职，言有物而行有恒。', adviceEn: 'Family harmony, each in their role; speak with substance and act with constancy.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 38, name: '火泽睽', nameEn: 'Opposition', upper: '离', lower: '兑', symbol: '䷥', element: '火', judgment: '小事吉。', judgmentEn: 'Opposition. In small matters, good fortune.', image: '上火下泽，睽；君子以同而异。', imageEn: 'Above, fire; below, the lake: the image of Opposition. The superior man preserves his inner union with others even when outwardly separated.', meaning: '睽卦象征乖离。求同存异，化解矛盾。', meaningEn: 'Kui symbolizes opposition. Seek common ground while preserving differences.', keywords: ['乖离','矛盾','对立','求同存异','化解'], keywordsEn: ['Opposition','Contradiction','Conflict','Common Ground','Resolution'], yaoTexts: ['悔亡，丧马勿逐，自复；见恶人无咎。','遇主于巷，无咎。','见舆曳，其牛掣，其人天且劓，无初有终。','睽孤，遇元夫，交孚，厉无咎。','悔亡，厥宗噬肤，往何咎。','睽孤，见豕负涂，载鬼一车，先张之弧，后说之弧，匪寇婚媾，往遇雨则吉。'], yaoTextsEn: ['Remorse disappears. If you lose your horse, do not run after it; it will come back of its own accord. When you see evil people, guard yourself against mistakes.','One meets his lord in a narrow street. No blame.','One sees the wagon dragged back, the oxen halted, a man\'s hair and nose cut off. Not a good beginning, but a good end.','Isolated through opposition, one meets a like-minded man with whom one can associate in good faith. Despite the danger, no blame.','Remorse disappears. The companion bites his way through the wrappings. If one goes to him, how could it be a mistake?','Isolated through opposition, one sees one\'s companion as a pig covered with dirt, as a wagon full of devils. First one draws a bow against him, then one lays the bow aside. He is not a robber; he will woo at the right time. As one goes, rain falls; then good fortune comes.'], advice: '求同存异，化解矛盾，大事化小。', adviceEn: 'Seek common ground, resolve conflicts, minimize issues.', fortune: '中平', fortuneEn: 'Neutral' },
  { number: 39, name: '水山蹇', nameEn: 'Obstruction', upper: '坎', lower: '艮', symbol: '䷦', element: '水', judgment: '利西南，不利东北；利见大人，贞吉。', judgmentEn: 'Obstruction. The southwest furthers. The northeast does not further. It furthers one to see the great man. Perseverance brings good fortune.', image: '山上有水，蹇；君子以反身修德。', imageEn: 'Water on the mountain: the image of Obstruction. The superior man turns his attention to himself and molds his character.', meaning: '蹇卦象征蹇难。遇到困难，宜反身修德。', meaningEn: 'Jian symbolizes difficulty. In hardship, turn inward and cultivate virtue.', keywords: ['困难','阻碍','反省','修养','等待'], keywordsEn: ['Difficulty','Obstruction','Introspection','Cultivation','Waiting'], yaoTexts: ['往蹇，来誉。','王臣蹇蹇，匪躬之故。','往蹇来反。','往蹇来连。','大蹇朋来。','往蹇来硕，吉；利见大人。'], yaoTextsEn: ['Going leads to obstructions, coming meets with praise.','The king\'s servant is beset by obstruction upon obstruction, but it is not his own fault.','Going leads to obstructions; hence he comes back.','Going leads to obstructions, coming leads to union.','In the midst of the greatest obstructions, friends come.','Going leads to obstructions, coming leads to great good fortune. It furthers one to see the great man.'], advice: '遇到困难，反身修德，等待时机。', adviceEn: 'In difficulty, cultivate virtue inwardly and wait for the right time.', fortune: '中平', fortuneEn: 'Neutral' },
  { number: 40, name: '雷水解', nameEn: 'Deliverance', upper: '震', lower: '坎', symbol: '䷧', element: '木', judgment: '利西南，无所往，其来复吉。有攸往，夙吉。', judgmentEn: 'Deliverance. The southwest furthers. If there is no longer anything where one has to go, return brings good fortune. If there is still something where one has to go, hastening brings good fortune.', image: '雷雨作，解；君子以赦过宥罪。', imageEn: 'Thunder and rain set in: the image of Deliverance. The superior man pardons mistakes and forgives misdeeds.', meaning: '解卦象征解脱。雷雨作而万物解，赦过宥罪。', meaningEn: 'Jie symbolizes deliverance. Thunder and rain release all things; pardon and forgive.', keywords: ['解脱','释放','宽恕','解决','新生'], keywordsEn: ['Deliverance','Release','Forgiveness','Resolution','Renewal'], yaoTexts: ['无咎。','田获三狐，得黄矢，贞吉。','负且乘，致寇至，贞吝。','解而拇，朋至斯孚。','君子维有解，吉；有孚于小人。','公用射隼，于高墉之上，获之，无不利。'], yaoTextsEn: ['Without blame.','One kills three foxes in the field and receives a yellow arrow. Perseverance brings good fortune.','If a man carries a burden on his back and nonetheless rides in a carriage, he thereby encourages robbers to draw near. Perseverance leads to humiliation.','Deliver yourself from your great toe. Then the companion comes, and him you can trust.','If only the superior man can deliver himself, it brings good fortune. Thus he proves to inferior men that he is in earnest.','The prince shoots at a hawk on a high wall. He kills it. Everything serves to further.'], advice: '解脱困境，宽恕他人，重新开始。', adviceEn: 'Free yourself from困境, forgive others, and start anew.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 41, name: '山泽损', nameEn: 'Decrease', upper: '艮', lower: '兑', symbol: '䷨', element: '土', judgment: '有孚，元吉，无咎，可贞，利有攸往。曷之用，二簋可用享。', judgmentEn: 'Decrease combined with sincerity brings about supreme good fortune without blame. One may be persevering in this. It furthers one to undertake something. How is this to be carried out? One may use two small bowls for the sacrifice.', image: '山下有泽，损；君子以惩忿窒欲。', imageEn: 'At the foot of the mountain, the lake: the image of Decrease. The superior man controls his anger and restrains his instincts.', meaning: '损卦象征减损。损下益上，但需诚信。', meaningEn: 'Sun symbolizes decrease. Sacrifice below to benefit above, but with sincerity.', keywords: ['减损','牺牲','节制','诚信','奉献'], keywordsEn: ['Decrease','Sacrifice','Temperance','Sincerity','Dedication'], yaoTexts: ['已事遄往，无咎，酌损之。','利贞，征凶，弗损益之。','三人行，则损一人；一人行，则得其友。','损其疾，使遄有喜，无咎。','或益之，十朋之龟弗克违，元吉。','弗损益之，无咎，贞吉，利有攸往，得臣无家。'], yaoTextsEn: ['Going quickly when one\'s tasks are finished is without blame. But one must reflect on how much one may decrease others.','Perseverance furthers. To undertake something brings misfortune. Without decreasing oneself, one is able to bring increase to others.','When three people journey together, their number decreases by one. When one man journeys alone, he finds a companion.','If a man decreases his faults, it is as if a sickness were quickly overcome. No blame.','Someone does indeed increase him. Ten pairs of tortoises cannot oppose it. Supreme good fortune.','If one is increased without depriving others, there is no blame. Perseverance brings good fortune. It furthers one to undertake something. One obtains servants but no longer has a separate home.'], advice: '适当减损，惩忿窒欲，以诚信待人。', adviceEn: 'Practice appropriate decrease, control anger and desires, treat others with sincerity.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 42, name: '风雷益', nameEn: 'Increase', upper: '巽', lower: '震', symbol: '䷩', element: '木', judgment: '利有攸往，利涉大川。', judgmentEn: 'Increase. It furthers one to undertake something. It furthers one to cross the great water.', image: '风雷，益；君子以见善则迁，有过则改。', imageEn: 'Wind and thunder: the image of Increase. The superior man, when he sees good, moves toward it; when he sees his errors, he corrects them.', meaning: '益卦象征增益。见善则迁，有过则改。', meaningEn: 'Yi symbolizes increase. Move toward goodness and correct errors.', keywords: ['增益','进步','改过','向善','发展'], keywordsEn: ['Increase','Progress','Correction','Goodness','Development'], yaoTexts: ['利用为大作，元吉，无咎。','或益之，十朋之龟弗克违，永贞吉。王用享于帝，吉。','益之用凶事，无咎。有孚中行，告公用圭。','中行，告公从。利用为依迁国。','有孚惠心，勿问元吉。有孚惠我德。','莫益之，或击之，立心勿恒，凶。'], yaoTextsEn: ['It furthers one to accomplish great deeds. Supreme good fortune. No blame.','Someone does indeed increase him; ten pairs of tortoises cannot oppose it. Constant perseverance brings good fortune. The king presents him before God. Good fortune.','One is enriched through unfortunate events. No blame, if you are sincere and walk in the middle, and report with a seal to the prince.','If you walk in the middle and report to the prince, he will follow. It furthers one to be used in moving the capital.','If in truth you have a kind heart, ask not. Supreme good fortune. Truly, kindness will be recognized as your virtue.','He brings increase to no one. Indeed, someone even strikes him. He does not keep his heart constantly steady. Misfortune.'], advice: '见善则迁，有过则改，增益德行。', adviceEn: 'Move toward goodness, correct errors, increase virtue.', fortune: '大吉', fortuneEn: 'Great Fortune' },
  { number: 43, name: '泽天夬', nameEn: 'Break-through', upper: '兑', lower: '乾', symbol: '䷪', element: '金', judgment: '扬于王庭，孚号，有厉，告自邑，不利即戎，利有攸往。', judgmentEn: 'Break-through. One must resolutely make the matter known at the court of the king. It must be announced truthfully. Danger. It is necessary to notify one\'s own city. It does not further to wage war. It furthers one to undertake something.', image: '泽上于天，夬；君子以施禄及下，居德则忌。', imageEn: 'The lake has risen up to heaven: the image of Break-through. The superior man dispenses riches downward and does not allow himself to be honored with riches.', meaning: '夬卦象征决断。果断决策，但需光明正大。', meaningEn: 'Guai symbolizes resolution. Make decisive decisions openly and aboveboard.', keywords: ['决断','果断','决策','光明','正义'], keywordsEn: ['Resolution','Decisiveness','Decision','Light','Justice'], yaoTexts: ['壮于前趾，往不胜为吝。','惕号，莫夜有戎，勿恤。','壮于頄，有凶。君子夬夬，独行遇雨，若濡有愠，无咎。','臀无肤，其行次且。牵羊悔亡，闻言不信。','苋陆夬夬，中行无咎。','无号，终有凶。'], yaoTextsEn: ['Powerful in the forward-striding toes. When one goes and is not equal to the task, one makes a mistake.','A cry of alarm. Arms at evening. Nothing to fear.','To be powerful in the cheekbones brings misfortune. The superior man is resolutely resolved. He walks alone and is caught in the rain. He is bespattered, and people murmur against him. No blame.','There is no skin on his thighs, and walking comes hard. If a man were to let himself be led like a sheep, remorse would disappear. But if these words are heard, they will not be believed.','In dealing with weeds, resolution is necessary. Walking in the middle remains free of blame.','No cry. In the end misfortune comes.'], advice: '果断决策，光明正大，但不可鲁莽。', adviceEn: 'Decide decisively and openly, but do not be reckless.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 44, name: '天风姤', nameEn: 'Coming to Meet', upper: '乾', lower: '巽', symbol: '䷫', element: '金', judgment: '女壮，勿用取女。', judgmentEn: 'Coming to Meet. The maiden is powerful. One should not marry such a maiden.', image: '天下有风，姤；后以施命诰四方。', imageEn: 'Under heaven, wind: the image of Coming to Meet. The prince thereby announces his orders and promulgates them to the four quarters of heaven.', meaning: '姤卦象征邂逅。一阴初生，需谨慎应对。', meaningEn: 'Gou symbolizes encounter. One yin is born; handle with care.', keywords: ['邂逅','相遇','谨慎','防范','开始'], keywordsEn: ['Encounter','Meeting','Caution','Prevention','Beginning'], yaoTexts: ['系于金柅，贞吉，有攸往，见凶，羸豕孚蹢躅。','包有鱼，无咎，不利宾。','臀无肤，其行次且，厉，无大咎。','包无鱼，起凶。','以杞包瓜，含章，有陨自天。','姤其角，无咎。'], yaoTextsEn: ['It must be checked with a brake of bronze. Perseverance brings good fortune. If one lets it go, misfortune comes. The piglet is barely past the time of suckling.','There is a fish in the tank. No blame. This does not further guests.','There is no skin on his thighs, and walking comes hard. If one is mindful of the danger, no great mistake is made.','No fish in the tank. This leads to misfortune.','The willow is bound round with the melon. Hidden lines. Something drops down from heaven.','He comes to meet with his horns. Humiliation. No blame.'], advice: '邂逅之时，需谨慎防范，不可大意。', adviceEn: 'In encounters, be cautious and vigilant.', fortune: '小凶', fortuneEn: 'Minor Misfortune' },
  { number: 45, name: '泽地萃', nameEn: 'Gathering Together', upper: '兑', lower: '坤', symbol: '䷬', element: '金', judgment: '亨。王假有庙，利见大人，亨，利贞。用大牲吉，利有攸往。', judgmentEn: 'Gathering Together. Success. The king approaches his temple. It furthers one to see the great man. This brings success. Perseverance furthers. To bring great offerings creates good fortune. It furthers one to undertake something.', image: '泽上于地，萃；君子以除戎器，戒不虞。', imageEn: 'The lake is over the earth: the image of Gathering Together. The superior man renews his weapons in order to meet the unforeseen.', meaning: '萃卦象征聚集。聚集众人，但需防备不测。', meaningEn: 'Cui symbolizes gathering. Gather people together, but prepare for the unexpected.', keywords: ['聚集','团结','防备','准备','聚会'], keywordsEn: ['Gathering','Unity','Preparation','Readiness','Assembly'], yaoTexts: ['有孚不终，乃乱乃萃，若号一握为笑，勿恤，往无咎。','引吉，无咎，孚乃利用禴。','萃如，嗟如，无攸利，往无咎，小吝。','大吉，无咎。','萃有位，无咎，匪孚，元永贞，悔亡。','赍咨涕洟，无咎。'], yaoTextsEn: ['If you are sincere, but not to the end, there will sometimes be confusion, sometimes gathering together. If you call out, then after one grasp of the hand you can laugh again. No blame. A going forward without blame.','Letting oneself be drawn brings good fortune and remains blameless. If one is sincere, it furthers one to bring even a small offering.','Gathering together amid sighs. Nothing that would further. Going is without blame. Slight humiliation.','Great good fortune. No blame.','If in gathering together one has position, this brings no blame. If there are some who are not yet sincerely in the work, sublime and enduring perseverance is needed. Then remorse disappears.','Lamenting and sighing, floods of tears. No blame.'], advice: '聚集之时，需真诚团结，防备不测。', adviceEn: 'In gathering, be sincere and united, and prepare for the unexpected.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 46, name: '地风升', nameEn: 'Pushing Upward', upper: '坤', lower: '巽', symbol: '䷭', element: '土', judgment: '元亨，用见大人，勿恤，南征吉。', judgmentEn: 'Pushing Upward has supreme success. One must see the great man. Fear not. Departure toward the south brings good fortune.', image: '地中生木，升；君子以顺德，积小以高大。', imageEn: 'Within the earth, wood grows: the image of Pushing Upward. The superior man of devoted character heaps up small things in order to achieve something high and great.', meaning: '升卦象征上升。循序渐进，积小成大。', meaningEn: 'Sheng symbolizes rising. Progress step by step, accumulate small to achieve great.', keywords: ['上升','进步','积累','发展','循序渐进'], keywordsEn: ['Rising','Progress','Accumulation','Development','Gradual'], yaoTexts: ['允升，大吉。','孚乃利用禴，无咎。','升虚邑。','王用亨于岐山，吉无咎。','贞吉，升阶。','冥升，利于不息之贞。'], yaoTextsEn: ['Pushing upward that meets with confidence brings great good fortune.','If one is sincere, it furthers one to bring even a small offering. No blame.','One pushes upward into an empty city.','The king offers sacrifice on Mount Chi. Good fortune. No blame.','Perseverance brings good fortune. One pushes upward by steps.','If one is misled into pushing upward, it is favorable to be perseveringly aware of the danger.'], advice: '循序渐进，积小成大，终能上升。', adviceEn: 'Progress step by step, accumulate small to achieve great.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 47, name: '泽水困', nameEn: 'Oppression', upper: '兑', lower: '坎', symbol: '䷮', element: '金', judgment: '亨，贞，大人吉，无咎，有言不信。', judgmentEn: 'Oppression. Success. Perseverance. The great man brings about good fortune. No blame. When one has something to say, it is not believed.', image: '泽无水，困；君子以致命遂志。', imageEn: 'There is no water in the lake: the image of Exhaustion. The superior man stakes his life on following his will.', meaning: '困卦象征困穷。泽无水则困，君子致命遂志。', meaningEn: 'Kun symbolizes oppression. A lake without water is exhausted; the superior man stakes his life on his will.', keywords: ['困穷','艰难','坚持','志向','忍耐'], keywordsEn: ['Oppression','Hardship','Perseverance','Will','Endurance'], yaoTexts: ['臀困于株木，入于幽谷，三岁不觌。','困于酒食，朱绂方来，利用享祀，征凶，无咎。','困于石，据于蒺藜，入于其宫，不见其妻，凶。','来徐徐，困于金车，吝，有终。','劓刖，困于赤绂，乃徐有说，利用祭祀。','困于葛藟，于臲卼，曰动悔。有悔，征吉。'], yaoTextsEn: ['One sits oppressed under a bare tree and strays into a gloomy valley. For three years one sees nothing.','One is oppressed while at meat and drink. The man with the scarlet knee bands is just coming. It furthers one to offer sacrifice. To set forth brings misfortune. No blame.','A man permits himself to be oppressed by stone, and leans on thorns and thistles. He enters his house and does not see his wife. Misfortune.','He comes very quietly, oppressed in a golden carriage. Humiliation, but the end is reached.','His nose and feet are cut off. Oppression at the hands of the man with the purple knee bands. Let him be liberated, then it furthers one to offer sacrifice.','He is oppressed by creeping vines. He moves uncertainly and says, "Movement brings remorse." If one feels remorse over this and makes a start, good fortune comes.'], advice: '困穷之时，坚守志向，终能解脱。', adviceEn: 'In oppression, hold to your will, and you will eventually be freed.', fortune: '小凶', fortuneEn: 'Minor Misfortune' },
  { number: 48, name: '水风井', nameEn: 'The Well', upper: '坎', lower: '巽', symbol: '䷯', element: '水', judgment: '改邑不改井，无丧无得，往来井井。汔至亦未繘井，羸其瓶，凶。', judgmentEn: 'The Well. The town may be changed, but the well cannot be changed. It neither decreases nor increases. They come and go and draw from the well. If one gets down almost to the water and the rope does not go all the way, or the jug breaks, it brings misfortune.', image: '木上有水，井；君子以劳民劝相。', imageEn: 'Wood is below, water above. The image of the Well. The superior man encourages the people at their work, and exhorts them to help one another.', meaning: '井卦象征水井。改邑不改井，恒常不变。', meaningEn: 'Jing symbolizes the well. The town may change, but the well remains constant.', keywords: ['水井','恒常','滋养','不变','资源'], keywordsEn: ['Well','Constancy','Nourishment','Permanence','Resource'], yaoTexts: ['井泥不食，旧井无禽。','井谷射鲋，瓮敝漏。','井渫不食，为我心恻，可用汲，王明，并受其福。','井甃，无咎。','井冽，寒泉食。','井收勿幕，有孚元吉。'], yaoTextsEn: ['One does not drink the mud of the well. No animals come to an old well.','At the wellhole one shoots fishes. The jug is broken and leaks.','The well is cleaned, but no one drinks from it. This is my heart\'s sorrow, for one might draw from it. If the king were clear-minded, good fortune might be enjoyed in common.','The well is being lined. No blame.','In the well there is a clear, cold spring from which one can drink.','One draws from the well without hindrance. It is dependable. Supreme good fortune.'], advice: '井养而不穷，恒常不变，滋养万物。', adviceEn: 'The well nourishes without end, constant and unchanging, nourishing all things.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 49, name: '泽火革', nameEn: 'Revolution', upper: '兑', lower: '离', symbol: '䷰', element: '金', judgment: '己日乃孚，元亨利贞，悔亡。', judgmentEn: 'Revolution. On your own day you are believed. Supreme success, furthering through perseverance. Remorse disappears.', image: '泽中有火，革；君子以治历明时。', imageEn: 'Fire in the lake: the image of Revolution. The superior man sets the calendar in order and makes the seasons clear.', meaning: '革卦象征变革。水火相息，革故鼎新。', meaningEn: 'Ge symbolizes revolution. Water and fire extinguish each other; discard the old and establish the new.', keywords: ['变革','革命','革新','鼎新','改革'], keywordsEn: ['Revolution','Change','Innovation','Renewal','Reform'], yaoTexts: ['巩用黄牛之革。','己日乃革之，征吉，无咎。','征凶，贞厉，革言三就，有孚。','悔亡，有孚改命，吉。','大人虎变，未占有孚。','君子豹变，小人革面，征凶，居贞吉。'], yaoTextsEn: ['He gets his tail in the water. No blame.','On the third day he is believed. Revolution. To set forth brings good fortune. No blame.','Starting brings misfortune. Perseverance brings danger. When talk of revolution has gone the rounds three times, one may commit himself, and men will believe him.','Remorse disappears. Men believe him. Changing the form of government brings good fortune.','The great man changes like a tiger. Even before he questions the oracle he is believed.','The superior man changes like a panther. The inferior man molts in the face. Starting brings misfortune. To remain persevering brings good fortune.'], advice: '变革之时，需诚信为先，革故鼎新。', adviceEn: 'In revolution, sincerity comes first; discard the old and establish the new.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 50, name: '火风鼎', nameEn: 'The Cauldron', upper: '离', lower: '巽', symbol: '䷱', element: '火', judgment: '元吉，亨。', judgmentEn: 'The Cauldron. Supreme good fortune. Success.', image: '木上有火，鼎；君子以正位凝命。', imageEn: 'Fire over wood: the image of the Cauldron. The superior man consolidates his fate by making his position correct.', meaning: '鼎卦象征鼎器。革故鼎新，正位凝命。', meaningEn: 'Ding symbolizes the cauldron. Discard the old and establish the new; consolidate your position.', keywords: ['鼎新','稳定','正位','凝命','成就'], keywordsEn: ['Renewal','Stability','Position','Consolidation','Achievement'], yaoTexts: ['鼎颠趾，利出否，得妾以其子，无咎。','鼎有实，我仇有疾，不我能即，吉。','鼎耳革，其行塞，雉膏不食，方雨亏悔，终吉。','鼎折足，覆公餗，其形渥，凶。','鼎黄耳金铉，利贞。','鼎玉铉，大吉，无不利。'], yaoTextsEn: ['A cauldron with legs upturned. Furthers removal of stagnating stuff. One takes a concubine for the sake of her son. No blame.','There is food in the cauldron. My comrades are envious, but they cannot harm me. Good fortune.','The handle of the cauldron is altered. One is impeded in his way of life. The fat of the pheasant is not eaten. Once rain falls, remorse is spent. In the end, good fortune.','The legs of the cauldron break. The prince\'s meal is spilled and his person is soiled. Misfortune.','The cauldron has yellow handles, golden carrying rings. Perseverance furthers.','The cauldron has rings of jade. Great good fortune. Nothing that would not act to further.'], advice: '革故鼎新，正位凝命，成就大业。', adviceEn: 'Discard the old and establish the new; consolidate your position and achieve great things.', fortune: '大吉', fortuneEn: 'Great Fortune' },
  { number: 51, name: '震为雷', nameEn: 'The Arousing', upper: '震', lower: '震', symbol: '䷲', element: '木', judgment: '亨。震来虩虩，笑言哑哑。震惊百里，不丧匕鬯。', judgmentEn: 'The Arousing (Shock, Thunder) brings success. Shock comes—oh, oh! Laughing words—ha, ha! The shock terrifies for a hundred miles, and he does not let fall the sacrificial spoon and chalice.', image: '洊雷，震；君子以恐惧修省。', imageEn: 'Thunder repeated: the image of Shock. The superior man in fear and trembling sets himself to examine his character.', meaning: '震卦象征震动。震惊百里，君子以恐惧修省。', meaningEn: 'Zhen symbolizes shock. Shock terrifies for a hundred miles; the superior man examines himself in fear and trembling.', keywords: ['震动','震惊','警觉','反省','行动'], keywordsEn: ['Shock','Tremor','Alertness','Introspection','Action'], yaoTexts: ['震来虩虩，后笑言哑哑，吉。','震来厉，亿丧贝，跻于九陵，勿逐，七日得。','震苏苏，震行无眚。','震遂泥。','震往来厉，亿无丧，有事。','震索索，视矍矍，征凶。震不于其躬，于其邻，无咎。婚媾有言。'], yaoTextsEn: ['Shock comes—oh, oh! Then follow laughing words—ha, ha! Good fortune.','Shock comes bringing danger. A hundred thousand times you lose your treasures and must climb the nine hills. Do not go in pursuit of them. After seven days you will get them back again.','Shock comes and makes one distraught. If shock spurs to action, one remains free of misfortune.','Shock is mired.','Shock goes hither and thither, danger. However, nothing at all is lost. Yet there are things to be done.','Shock brings ruin and terrified gazing around. Going forward brings misfortune. If it has not yet touched one\'s own body but has reached one\'s neighbor first, there is no blame. One\'s comrades have something to talk about.'], advice: '震惊之时，保持镇定，反省修身。', adviceEn: 'In shock, remain calm and examine yourself.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 52, name: '艮为山', nameEn: 'Keeping Still', upper: '艮', lower: '艮', symbol: '䷳', element: '土', judgment: '艮其背，不获其身，行其庭，不见其人，无咎。', judgmentEn: 'Keeping Still. Keeping his back still so that he no longer feels his body. He goes into his courtyard and does not see his people. No blame.', image: '兼山，艮；君子以思不出其位。', imageEn: 'Mountains standing close together: the image of Keeping Still. The superior man does not permit his thoughts to go beyond his situation.', meaning: '艮卦象征止。止于当止，思不出其位。', meaningEn: 'Gen symbolizes stillness. Stop when you should stop; do not let thoughts go beyond your position.', keywords: ['止','静止','节制','内省','守位'], keywordsEn: ['Stopping','Stillness','Temperance','Introspection','Position'], yaoTexts: ['艮其趾，无咎，利永贞。','艮其腓，不拯其随，其心不快。','艮其限，列其夤，厉薰心。','艮其身，无咎。','艮其辅，言有序，悔亡。','敦艮，吉。'], yaoTextsEn: ['Keeping his toes still. No blame. Continued perseverance furthers.','Keeping his calves still. He cannot rescue him whom he follows. His heart is not glad.','Keeping his hips still. Making his sacrum stiff. Dangerous. The heart suffocates.','Keeping his trunk still. No blame.','Keeping his jaws still. The words are well ordered. Remorse disappears.','Noblehearted keeping still. Good fortune.'], advice: '止于当止，思不出其位，内省修身。', adviceEn: 'Stop when appropriate; do not let thoughts go beyond your position; cultivate yourself inwardly.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 53, name: '风山渐', nameEn: 'Development', upper: '巽', lower: '艮', symbol: '䷴', element: '木', judgment: '女归吉，利贞。', judgmentEn: 'Development. The maiden is given in marriage. Good fortune. Perseverance furthers.', image: '山上有木，渐；君子以居贤德，善俗。', imageEn: 'On the mountain, a tree: the image of Development. The superior man abides in dignity and virtue, in order to improve the customs.', meaning: '渐卦象征渐进。循序渐进，积小成大。', meaningEn: 'Jian symbolizes gradual development. Progress step by step, accumulate small to achieve great.', keywords: ['渐进','发展','积累','循序渐进','稳定'], keywordsEn: ['Gradual','Development','Accumulation','Step by Step','Stability'], yaoTexts: ['鸿渐于干，小子厉，有言，无咎。','鸿渐于磐，饮食衎衎，吉。','鸿渐于陆，夫征不复，妇孕不育，凶；利御寇。','鸿渐于木，或得其桷，无咎。','鸿渐于陵，妇三岁不孕，终莫之胜，吉。','鸿渐于逵，其羽可用为仪，吉。'], yaoTextsEn: ['The wild goose gradually draws near the shore. The young son is in danger. There is talk. No blame.','The wild goose gradually draws near the cliff. Eating and drinking in peace and concord. Good fortune.','The wild goose gradually draws near the plateau. The man goes forth and does not return. The woman carries a child but does not bring it forth. Misfortune. It furthers one to fight off robbers.','The wild goose gradually draws near the tree. Perhaps it will find a flat branch. No blame.','The wild goose gradually draws near the summit. For three years the woman has no child. In the end nothing can hinder her. Good fortune.','The wild goose gradually draws near the cloud heights. Its feathers can be used for the sacred dance. Good fortune.'], advice: '循序渐进，不可急于求成，稳步发展。', adviceEn: 'Progress gradually; do not rush; develop steadily.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 54, name: '雷泽归妹', nameEn: 'The Marrying Maiden', upper: '震', lower: '兑', symbol: '䷵', element: '木', judgment: '征凶，无攸利。', judgmentEn: 'The Marrying Maiden. Undertakings bring misfortune. Nothing that would further.', image: '泽上有雷，归妹；君子以永终知敝。', imageEn: 'Thunder over the lake: the image of the Marrying Maiden. The superior man understands the transitory in the light of the eternity of the end.', meaning: '归妹卦象征嫁娶。少女从长男，需知敝永终。', meaningEn: 'Gui Mei symbolizes the marrying maiden. The young girl follows the older man; know the transitory in light of eternity.', keywords: ['嫁娶','从属','婚姻','少女','归宿'], keywordsEn: ['Marriage','Subordination','Wedding','Young Girl','Destiny'], yaoTexts: ['归妹以娣，跛能履，征吉。','眇能视，利幽人之贞。','归妹以须，反归以娣。','归妹愆期，迟归有时。','帝乙归妹，其君之袂，不如其娣之袂良，月几望，吉。','女承筐无实，士刲羊无血，无攸利。'], yaoTextsEn: ['The marrying maiden as a concubine. A lame man who is able to tread. Undertakings bring good fortune.','A one-eyed man who is able to see. The perseverance of a solitary man furthers.','The marrying maiden as a slave. She marries as a concubine.','The marrying maiden draws out the time. She marries belatedly.','The sovereign I gave his daughter in marriage. The embroidered garments of the princess were not as gorgeous as those of the maidservant. The moon that is nearly full brings good fortune.','The woman holds the basket, but there are no fruits in it. The man stabs the sheep, but no blood flows. Nothing that acts to further.'], advice: '婚姻大事，需谨慎对待，知敝永终。', adviceEn: 'Marriage is a serious matter; handle with care and understand the long-term.', fortune: '小凶', fortuneEn: 'Minor Misfortune' },
  { number: 55, name: '雷火丰', nameEn: 'Abundance', upper: '震', lower: '离', symbol: '䷶', element: '木', judgment: '亨，王假之，勿忧，宜日中。', judgmentEn: 'Abundance has success. The king attains abundance. Be not sad. Be like the sun at midday.', image: '雷电皆至，丰；君子以折狱致刑。', imageEn: 'Both thunder and lightning come: the image of Abundance. The superior man decides lawsuits and carries out punishments.', meaning: '丰卦象征丰盛。雷电皆至，万物丰盛。', meaningEn: 'Feng symbolizes abundance. Thunder and lightning come together; all things flourish.', keywords: ['丰盛','繁荣','光明','盛大','成功'], keywordsEn: ['Abundance','Prosperity','Light','Grandeur','Success'], yaoTexts: ['遇其配主，虽旬无咎，往有尚。','丰其蔀，日中见斗，往得疑疾，有孚发若，吉。','丰其沛，日中见沬，折其右肱，无咎。','丰其蔀，日中见斗，遇其夷主，吉。','来章，有庆誉，吉。','丰其屋，蔀其家，窥其户，阒其无人，三岁不觌，凶。'], yaoTextsEn: ['He meets his mate. Though they are ten days together, there is no blame. A going forth brings good fortune.','The curtain is of such fullness that the polestars can be seen at noon. Through going one meets with mistrust and hate. If one rouses him through truth, good fortune comes.','The underbrush is of such abundance that the small stars can be seen at noon. He breaks his right arm. No blame.','The curtain is of such fullness that the polestars can be seen at noon. He meets his ruler, who is of like kind. Good fortune.','Lines are coming. Blessing and fame draw near. Good fortune.','His house is in a state of abundance. He screens off his family. He peers through the gate and no longer sees anyone. For three years he sees nothing. Misfortune.'], advice: '丰盛之时，宜折狱致刑，公正执法。', adviceEn: 'In abundance, be just and enforce laws fairly.', fortune: '大吉', fortuneEn: 'Great Fortune' },
  { number: 56, name: '火山旅', nameEn: 'The Wanderer', upper: '离', lower: '艮', symbol: '䷷', element: '火', judgment: '小亨，旅贞吉。', judgmentEn: 'The Wanderer. Success through smallness. Perseverance brings good fortune to the wanderer.', image: '山上有火，旅；君子以明慎用刑，而不留狱。', imageEn: 'Fire on the mountain: the image of the Wanderer. The superior man, in accordance with this, is clear-minded and cautious in imposing penalties, and does not continue a prosecution beyond its proper term.', meaning: '旅卦象征旅行。出门在外，需谨慎行事。', meaningEn: 'Lu symbolizes the wanderer. When away from home, act with caution.', keywords: ['旅行','漂泊','谨慎','适应','独立'], keywordsEn: ['Travel','Wandering','Caution','Adaptation','Independence'], yaoTexts: ['旅琐琐，斯其所取灾。','旅即次，怀其资，得童仆贞。','旅焚其次，丧其童仆，贞厉。','旅于处，得其资斧，我心不快。','射雉一矢亡，终以誉命。','鸟焚其巢，旅人先笑后号咷。丧牛于易，凶。'], yaoTextsEn: ['If the wanderer busies himself with trivial things, he draws down misfortune upon himself.','The wanderer comes to an inn. He has his property with him. He wins the steadfastness of a young servant.','The wanderer\'s inn burns down. He loses the steadfastness of his young servant. Danger.','The wanderer rests in a shelter. He obtains his property and an ax. My heart is not glad.','He shoots a pheasant. It drops with the first arrow. In the end this brings him praise and a high charge.','The bird\'s nest burns up. The wanderer laughs at first, then must needs lament and weep. Through carelessness he loses his cow. Misfortune.'], advice: '出门在外，谨慎行事，明慎用刑。', adviceEn: 'When traveling, act cautiously and be judicious.', fortune: '中平', fortuneEn: 'Neutral' },
  { number: 57, name: '巽为风', nameEn: 'The Gentle', upper: '巽', lower: '巽', symbol: '䷸', element: '木', judgment: '小亨，利有攸往，利见大人。', judgmentEn: 'The Gentle. Success through what is small. It furthers one to have somewhere to go. It furthers one to see the great man.', image: '随风，巽；君子以申命行事。', imageEn: 'Winds following one upon the other: the image of the Gentle. The superior man spreads his commands abroad and carries out his affairs.', meaning: '巽卦象征顺从。随风巽，君子以申命行事。', meaningEn: 'Xun symbolizes gentleness. Wind follows wind; the superior man spreads his commands and carries out affairs.', keywords: ['顺从','进入','渗透','灵活','谦逊'], keywordsEn: ['Gentleness','Penetration','Flexibility','Humility','Adaptation'], yaoTexts: ['进退，利武人之贞。','巽在床下，用史巫纷若，吉无咎。','频巽，吝。','悔亡，田获三品。','贞吉悔亡，无不利。无初有终，先庚三日，后庚三日，吉。','巽在床下，丧其资斧，贞凶。'], yaoTextsEn: ['In advancing and in retreating, the perseverance of a warrior furthers.','Penetration under the bed. Priests and magicians are used in great number. Good fortune. No blame.','Repeated penetration. Humiliation.','Remorse disappears. During the hunt three kinds of game are caught.','Perseverance brings good fortune. Remorse disappears. Nothing that does not further. No beginning, but an end. Before the change, three days. After the change, three days. Good fortune.','Penetration under the bed. He loses his property and his ax. Perseverance brings misfortune.'], advice: '随风而动，柔顺行事，但不可丧失主见。', adviceEn: 'Move with the wind, act gently, but do not lose your own judgment.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 58, name: '兑为泽', nameEn: 'The Joyous', upper: '兑', lower: '兑', symbol: '䷹', element: '金', judgment: '亨，利贞。', judgmentEn: 'The Joyous. Success. Perseverance furthers.', image: '丽泽，兑；君子以朋友讲习。', imageEn: 'Lakes resting one on the other: the image of the Joyous. The superior man joins with his friends for discussion and practice.', meaning: '兑卦象征喜悦。丽泽兑，君子以朋友讲习。', meaningEn: 'Dui symbolizes joy. Lakes reflecting each other; the superior man discusses and practices with friends.', keywords: ['喜悦','交流','口舌','和谐','愉悦'], keywordsEn: ['Joy','Exchange','Eloquence','Harmony','Pleasure'], yaoTexts: ['和兑，吉。','孚兑，吉，悔亡。','来兑，凶。','商兑，未宁，介疾有喜。','孚于剥，有厉。','引兑。'], yaoTextsEn: ['Contented joyousness. Good fortune.','Sincere joyousness. Good fortune. Remorse disappears.','Coming joyousness. Misfortune.','Joyousness that is weighed is not at peace. After ridding himself of mistakes a man has joy.','Sincerity toward disintegrating influences is dangerous.','Seductive joyousness.'], advice: '喜悦之时，与朋友讲习，但不可沉溺。', adviceEn: 'In joy, discuss and practice with friends, but do not indulge.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 59, name: '风水涣', nameEn: 'Dispersion', upper: '巽', lower: '坎', symbol: '䷺', element: '木', judgment: '亨。王假有庙，利涉大川，利贞。', judgmentEn: 'Dispersion. Success. The king approaches his temple. It furthers one to cross the great water. Perseverance furthers.', image: '风行水上，涣；先王以享于帝立庙。', imageEn: 'The wind drives over the water: the image of Dispersion. The kings of antiquity offered sacrifice to the Lord and built temples.', meaning: '涣卦象征涣散。风行水上，先王以享于帝立庙。', meaningEn: 'Huan symbolizes dispersion. Wind drives over water; the ancient kings offered sacrifice and built temples.', keywords: ['涣散','解散','化解','聚集','祭祀'], keywordsEn: ['Dispersion','Dissolution','Resolution','Gathering','Sacrifice'], yaoTexts: ['用拯马壮，吉。','涣奔其机，悔亡。','涣其躬，无悔。','涣其群，元吉。涣有丘，匪夷所思。','涣汗其大号，涣王居，无咎。','涣其血，去逖出，无咎。'], yaoTextsEn: ['He brings help with the strength of a horse. Good fortune.','At the dissolution he hurries to that which supports him. Remorse disappears.','He dissolves his self. No remorse.','He dissolves his bond with his group. Supreme good fortune. Dispersion leads in turn to accumulation. This is something that ordinary men do not think about.','His loud cries are as dissolving as sweat. Dissolution! A king abides without blame.','He dissolves his blood. Departing, keeping at a distance, going out, is without blame.'], advice: '涣散之时，宜聚集人心，化解矛盾。', adviceEn: 'In dispersion, gather people\'s hearts and resolve conflicts.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 60, name: '水泽节', nameEn: 'Limitation', upper: '坎', lower: '兑', symbol: '䷻', element: '水', judgment: '亨。苦节不可贞。', judgmentEn: 'Limitation. Success. Galling limitation must not be persevered in.', image: '泽上有水，节；君子以制数度，议德行。', imageEn: 'Water over lake: the image of Limitation. The superior man creates number and measure, and discusses virtue and conduct.', meaning: '节卦象征节制。泽上有水，君子以制数度议德行。', meaningEn: 'Jie symbolizes limitation. Water over lake; the superior man creates measures and discusses virtue.', keywords: ['节制','限制','适度','规矩','节约'], keywordsEn: ['Limitation','Restriction','Moderation','Rules','Economy'], yaoTexts: ['不出户庭，无咎。','不出门庭，凶。','不节若，则嗟若，无咎。','安节，亨。','甘节，吉；往有尚。','苦节，贞凶，悔亡。'], yaoTextsEn: ['Not going out of the door and the courtyard is without blame.','Not going out of the gate and the courtyard brings misfortune.','He who knows no limitation will have cause to lament. No blame.','Contented limitation. Success.','Sweet limitation brings good fortune. Going on brings good fortune.','Galling limitation. Perseverance brings misfortune. Remorse disappears.'], advice: '适度节制，不可过度，制数度议德行。', adviceEn: 'Practice moderation, not excess; create measures and discuss virtue.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 61, name: '风泽中孚', nameEn: 'Inner Truth', upper: '巽', lower: '兑', symbol: '䷼', element: '木', judgment: '豚鱼吉，利涉大川，利贞。', judgmentEn: 'Inner Truth. Pigs and fishes. Good fortune. It furthers one to cross the great water. Perseverance furthers.', image: '泽上有风，中孚；君子以议狱缓死。', imageEn: 'Wind over lake: the image of Inner Truth. The superior man discusses criminal cases in order to delay executions.', meaning: '中孚卦象征诚信。泽上有风，君子以议狱缓死。', meaningEn: 'Zhong Fu symbolizes inner truth. Wind over lake; the superior man discusses cases to delay executions.', keywords: ['诚信','真实','信任','内心','沟通'], keywordsEn: ['Truth','Sincerity','Trust','Inner','Communication'], yaoTexts: ['虞吉，有他不燕。','鸣鹤在阴，其子和之，我有好爵，吾与尔靡之。','得敌，或鼓或罢，或泣或歌。','月几望，马匹亡，无咎。','有孚挛如，无咎。','翰音登于天，贞凶。'], yaoTextsEn: ['Being prepared brings good fortune. If there are secret designs, it is disquieting.','A crane calling in the shade. Its young answers it. I have a good goblet. I will share it with you.','He finds a comrade. Now he beats the drum, now he stops. Now he sobs, now he sings.','The moon is nearly full. If the horse goes astray, no blame.','He possesses truth, which links together. No blame.','Cockcrow penetrating to heaven. Perseverance brings misfortune.'], advice: '诚信为本，内心真实，与人沟通。', adviceEn: 'Sincerity is the foundation; be true within and communicate with others.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 62, name: '雷山小过', nameEn: 'Preponderance of the Small', upper: '震', lower: '艮', symbol: '䷽', element: '木', judgment: '亨，利贞，可小事，不可大事。飞鸟遗之音，不宜上宜下，大吉。', judgmentEn: 'Preponderance of the Small. Success. Perseverance furthers. Small things may be done; great things should not be done. The flying bird brings the message: it is not well to strive upward, it is well to remain below. Great good fortune.', image: '山上有雷，小过；君子以行过乎恭，丧过乎哀，用过乎俭。', imageEn: 'Thunder on the mountain: the image of Preponderance of the Small. The superior man exceeds in his conduct in respect to reverence, in mourning in respect to grief, and in his expenditures in respect to thrift.', meaning: '小过卦象征小有过越。宜小事，不宜大事。', meaningEn: 'Xiao Guo symbolizes small excess. Suitable for small matters, not for great ones.', keywords: ['小过','过越','谨慎','小事','适度'], keywordsEn: ['Small Excess','Transgression','Caution','Small Matters','Moderation'], yaoTexts: ['飞鸟以凶。','过其祖，遇其妣；不及其君，遇其臣；无咎。','弗过防之，从或戕之，凶。','无咎，弗过遇之。往厉必戒，勿用永贞。','密云不雨，自我西郊，公弋取彼在穴。','弗遇过之，飞鸟离之，凶，是谓灾眚。'], yaoTextsEn: ['The bird meets with misfortune.','He passes by his ancestor and meets his ancestress. He does not reach his prince but meets his official. No blame.','If one does not exceed in his defenses, he will be attacked. Misfortune.','No blame. To pass by without exceeding is not a mistake. To go forward brings danger. One must be on guard. Do not act constantly.','Dense clouds, no rain from our western region. The prince shoots and hits him who is in the cave.','He passes him by, not meeting him. The flying bird leaves him. Misfortune. This means bad luck and injury.'], advice: '小事可过，大事不可过，谨慎行事。', adviceEn: 'Small excess is acceptable, but not in great matters; act with caution.', fortune: '中吉', fortuneEn: 'Moderate Fortune' },
  { number: 63, name: '水火既济', nameEn: 'After Completion', upper: '坎', lower: '离', symbol: '䷾', element: '水', judgment: '亨，小利贞，初吉终乱。', judgmentEn: 'After Completion. Success in small matters. Perseverance furthers. At the beginning good fortune, at the end disorder.', image: '水在火上，既济；君子以思患而豫防之。', imageEn: 'Water over fire: the image of the condition in After Completion. The superior man takes thought of misfortune and arms himself against it in advance.', meaning: '既济卦象征既成。水火既济，初吉终乱。', meaningEn: 'Ji Ji symbolizes completion. Water over fire; good at first but disorder in the end.', keywords: ['完成','成功','警惕','预防','守成'], keywordsEn: ['Completion','Success','Vigilance','Prevention','Conservation'], yaoTexts: ['曳其轮，濡其尾，无咎。','妇丧其茀，勿逐，七日得。','高宗伐鬼方，三年克之，小人勿用。','繻有衣袽，终日戒。','东邻杀牛，不如西邻之禴祭，实受其福。','濡其首，厉。'], yaoTextsEn: ['He brakes his wheels. He spills his water. The end brings good fortune.','The woman loses the curtain of her carriage. Do not run after it; on the seventh day you will get it.','The Illustrious Ancestor disciplines the Devil\'s Country. After three years he conquers it. Inferior people must not be employed.','The finest clothes turn to rags. Be careful all day long.','The neighbor in the east who slaughters an ox does not attain as much real happiness as the neighbor in the west with his small offering.','He gets his head in the water. Danger.'], advice: '成功之后，需思患预防，不可大意。', adviceEn: 'After success, think of misfortune and prevent it; do not be careless.', fortune: '吉', fortuneEn: 'Fortune' },
  { number: 64, name: '火水未济', nameEn: 'Before Completion', upper: '离', lower: '坎', symbol: '䷿', element: '火', judgment: '亨，小狐汔济，濡其尾，无攸利。', judgmentEn: 'Before Completion. Success. But if the little fox, after nearly completing the crossing, gets his tail in the water, there is nothing that would further.', image: '火在水上，未济；君子以慎辨物居方。', imageEn: 'Fire over water: the image of the condition before transition. The superior man is careful in the differentiation of things, so that each finds its place.', meaning: '未济卦象征未成。火在水上，尚未完成。', meaningEn: 'Wei Ji symbolizes incompletion. Fire over water; not yet completed.', keywords: ['未完成','开始','希望','谨慎','转变'], keywordsEn: ['Incompletion','Beginning','Hope','Caution','Transition'], yaoTexts: ['濡其尾，吝。','曳其轮，贞吉。','未济，征凶，利涉大川。','贞吉，悔亡，震用伐鬼方，三年有赏于大国。','贞吉，无悔，君子之光，有孚，吉。','濡其首，厉。'], yaoTextsEn: ['He gets his tail in the water. Humiliation.','He brakes his wheels. Perseverance brings good fortune.','Before completion, attack brings misfortune. It furthers one to cross the great water.','Perseverance brings good fortune. Remorse disappears. Shock, thus to discipline the Devil\'s Country. For three years, great rewards are given.','Perseverance brings good fortune. No remorse. The light of the superior man is true. Good fortune.','He gets his head in the water. Danger.'], advice: '尚未完成，需谨慎行事，把握时机。', adviceEn: 'Not yet completed; act with caution and seize the opportunity.', fortune: '中平', fortuneEn: 'Neutral' },
];

export const GUA64_MAP: Record<string, Gua64> = Object.fromEntries(GUA64_LIST.map(g => [g.name, g]));

export function getGua64(name: string): Gua64 | undefined { return GUA64_MAP[name]; }
export function getGua64ByNumber(num: number): Gua64 | undefined { return GUA64_LIST.find(g => g.number === num); }
export function getGua64ByUpperLower(upper: string, lower: string): Gua64 | undefined { return GUA64_LIST.find(g => g.upper === upper && g.lower === lower); }
export function getGua64BySymbol(symbol: string): Gua64 | undefined { return GUA64_LIST.find(g => g.symbol === symbol); }
export function getGua64ByFortune(fortune: Gua64['fortune']): Gua64[] { return GUA64_LIST.filter(g => g.fortune === fortune); }
export function getRandomGua64(): Gua64 { return GUA64_LIST[Math.floor(Math.random() * GUA64_LIST.length)]; }
export function getGua64ByElement(element: string): Gua64[] { return GUA64_LIST.filter(g => g.element === element); }
